//go:generate mockgen -destination mock_objecttree/mock_objecttree.go github.com/anyproto/any-sync/commonspace/object/tree/objecttree ObjectTree,Storage
package objecttree

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/anyproto/any-sync/util/debug"

	"go.uber.org/zap"

	"github.com/anyproto/any-sync/commonspace/object/acl/list"
	"github.com/anyproto/any-sync/commonspace/object/tree/treechangeproto"
	"github.com/anyproto/any-sync/util/crypto"
	"github.com/anyproto/any-sync/util/slice"
)

var (
	ErrHasInvalidChanges = errors.New("the change is invalid")
	ErrNoCommonSnapshot  = errors.New("trees doesn't have a common snapshot")
	ErrNoChangeInTree    = errors.New("no such change in tree")
	ErrMissingKey        = errors.New("missing current read key")
	ErrDerived           = errors.New("expect >= 2 changes in derived tree")
	ErrDeleted           = errors.New("object tree is deleted")
	ErrNoAclHead         = errors.New("no acl head")
)

type (
	Updater         = func(tree ObjectTree, md Mode) error
	ChangeValidator = func(change StorageChange) error
)

type AddResultSummary int

type AddResult struct {
	OldHeads []string
	Heads    []string
	Added    []StorageChange

	Mode Mode
}

func (a AddResult) RawChanges() []*treechangeproto.RawTreeChangeWithId {
	rawChanges := make([]*treechangeproto.RawTreeChangeWithId, 0, len(a.Added))
	for _, ch := range a.Added {
		rawChanges = append(rawChanges, ch.RawTreeChangeWithId())
	}
	return rawChanges
}

type RawChangesPayload struct {
	NewHeads     []string
	RawChanges   []*treechangeproto.RawTreeChangeWithId
	SnapshotPath []string
}

type ChangeIterateFunc = func(change *Change) bool
type ChangeConvertFunc = func(change *Change, decrypted []byte) (any, error)

type TryLocker interface {
	sync.Locker
	TryLock() bool
}

type ReadableObjectTree interface {
	TryLocker

	Id() string
	Header() *treechangeproto.RawTreeChangeWithId
	UnmarshalledHeader() *Change
	ChangeInfo() *treechangeproto.TreeChangeInfo
	Heads() []string
	Root() *Change
	Len() int
	IsDerived() bool

	AclList() list.AclList

	HasChanges(...string) bool
	GetChange(string) (*Change, error)

	Debug(parser DescriptionParser) (DebugInfo, error)
	IterateRoot(convert ChangeConvertFunc, iterate ChangeIterateFunc) error
	IterateFrom(id string, convert ChangeConvertFunc, iterate ChangeIterateFunc) error
	IterateAfterAddSeq(ctx context.Context, addSeq uint64, convert ChangeConvertFunc, iterate ChangeIterateFunc) error
}

type ObjectTree interface {
	ReadableObjectTree

	SnapshotPath() ([]string, error)
	ChangesAfterCommonSnapshotLoader(snapshotPath, heads []string) (LoadIterator, error)

	Storage() Storage

	AddContent(ctx context.Context, content SignableChangeContent) (AddResult, error)
	AddContentWithValidator(ctx context.Context, content SignableChangeContent, validate ChangeValidator) (AddResult, error)
	AddRawChanges(ctx context.Context, changes RawChangesPayload) (AddResult, error)
	AddRawChangesWithUpdater(ctx context.Context, changes RawChangesPayload, updater Updater) (AddResult, error)

	UnpackChange(raw *treechangeproto.RawTreeChangeWithId) (data []byte, err error)
	PrepareChange(content SignableChangeContent) (res *treechangeproto.RawTreeChangeWithId, err error)

	Delete() error
	Close() error
	SetFlusher(flusher Flusher)
	SetDeferredUpdater(deferred bool)
	TryClose(objectTTL time.Duration) (bool, error)
}

type objectTree struct {
	storage       Storage
	changeBuilder ChangeBuilder
	validator     ObjectTreeValidator
	treeBuilder   *treeBuilder
	aclList       list.AclList
	flusher       Flusher

	id      string
	rawRoot *treechangeproto.RawTreeChangeWithId
	root    *Change
	tree    *Tree

	keys            map[string]crypto.SymKey
	currentReadKey  crypto.SymKey
	isDeleted       bool
	deferredUpdater bool

	// buffers
	difSnapshotBuf  []*treechangeproto.RawTreeChangeWithId
	newChangesBuf   []*Change
	newSnapshotsBuf []*Change

	snapshotPath []string

	sync.Mutex
}

func (ot *objectTree) rebuildFromStorage(theirHeads, theirSnapshotPath []string, newChanges []*Change) (added []*Change, err error) {
	var (
		ourPath []string
		oldTree = ot.tree
	)
	if theirHeads != nil {
		// TODO: add error handling
		ourPath, err = ot.SnapshotPath()
		if err != nil {
			return nil, fmt.Errorf("rebuild from storage: %w", err)
		}
	}
	ot.tree, added, err = ot.treeBuilder.buildWithAdded(treeBuilderOpts{
		theirHeads:        theirHeads,
		ourSnapshotPath:   ourPath,
		theirSnapshotPath: theirSnapshotPath,
		newChanges:        newChanges,
	})
	if err != nil {
		ot.tree = oldTree
		return
	}

	// in case there are new heads
	if theirHeads != nil && oldTree != nil {
		// checking that old root is still in tree
		rootCh, rootExists := ot.tree.attached[oldTree.RootId()]

		// checking the case where theirHeads were actually below prevHeads
		// so if we did load some extra data in the tree, let's reduce it to old root
		if slice.UnsortedEquals(oldTree.headIds, ot.tree.headIds) && rootExists && ot.tree.RootId() != oldTree.RootId() {
			ot.tree.makeRootAndRemove(rootCh)
		}
	}

	// during building the tree we may have marked some changes as possible roots,
	// but obviously they are not roots, because of the way how we construct the tree
	ot.tree.clearPossibleRoots()

	// it is a good question whether we need to validate everything
	// because maybe we can trust the stuff that is already in the storage
	return added, ot.validateTree(nil)
}

func (ot *objectTree) Id() string {
	return ot.id
}

func (ot *objectTree) IsDerived() bool {
	return ot.root.IsDerived
}

func (ot *objectTree) Len() int {
	return ot.tree.Len()
}

func (ot *objectTree) AclList() list.AclList {
	return ot.aclList
}

func (ot *objectTree) Header() *treechangeproto.RawTreeChangeWithId {
	return ot.rawRoot
}

func (ot *objectTree) SetFlusher(flusher Flusher) {
	ot.flusher = flusher
}

func (ot *objectTree) SetDeferredUpdater(deferred bool) {
	ot.deferredUpdater = deferred
}

func (ot *objectTree) UnmarshalledHeader() *Change {
	return ot.root
}

func (ot *objectTree) ChangeInfo() *treechangeproto.TreeChangeInfo {
	return ot.root.Model.(*treechangeproto.TreeChangeInfo)
}

func (ot *objectTree) Storage() Storage {
	return ot.storage
}

func (ot *objectTree) GetChange(id string) (*Change, error) {
	if ot.isDeleted {
		return nil, ErrDeleted
	}
	if ch, ok := ot.tree.attached[id]; ok {
		return ch, nil
	}
	return nil, ErrNoChangeInTree
}

func (ot *objectTree) logUseWhenUnlocked() {
	// this is needed to check when we use the tree not under the lock
	if ot.TryLock() {
		log.With(zap.String("treeId", ot.id), zap.String("stack", debug.StackCompact(true))).Error("use tree when unlocked")
		ot.Unlock()
	}
}

func (ot *objectTree) AddContent(ctx context.Context, content SignableChangeContent) (res AddResult, err error) {
	return ot.AddContentWithValidator(ctx, content, nil)
}

func (ot *objectTree) AddContentWithValidator(ctx context.Context, content SignableChangeContent, validator func(change StorageChange) error) (res AddResult, err error) {
	if ot.isDeleted {
		err = ErrDeleted
		return
	}
	ot.logUseWhenUnlocked()
	payload, err := ot.prepareBuilderContent(content)
	if err != nil {
		return
	}

	// saving old heads
	oldHeads := make([]string, 0, len(ot.tree.Heads()))
	oldHeads = append(oldHeads, ot.tree.Heads()...)

	objChange, rawChange, err := ot.changeBuilder.Build(payload)
	if err != nil {
		return
	}
	// validating the change just in case to avoid possible bugs
	err = ot.validateTree([]*Change{objChange})
	if err != nil {
		err = fmt.Errorf("error validating added change: %w", err)
		return
	}
	objChange.OrderId = lexId.Next(ot.tree.attached[ot.tree.lastIteratedHeadId].OrderId)
	commonSnapshot := ot.tree.root.Id
	if content.IsSnapshot {
		objChange.SnapshotCounter = ot.tree.root.SnapshotCounter + 1
		commonSnapshot = objChange.Id
	}
	storageChange := StorageChange{
		RawChange:       rawChange.RawChange,
		PrevIds:         objChange.PreviousIds,
		Id:              objChange.Id,
		SnapshotCounter: objChange.SnapshotCounter,
		SnapshotId:      objChange.SnapshotId,
		OrderId:         objChange.OrderId,
		ChangeSize:      len(rawChange.RawChange),
	}
	if validator != nil {
		err = validator(storageChange)
		if err != nil {
			return
		}
	}
	// the tree takes the change only once it is stored: a change the storage
	// refused must not become the parent of the next one
	added := []StorageChange{storageChange}
	err = ot.storage.AddAll(ctx, added, []string{objChange.Id}, commonSnapshot)
	if err != nil {
		return
	}
	if content.IsSnapshot {
		// clearing tree, because we already saved everything in the last snapshot
		ot.tree = &Tree{}
	}
	err = ot.tree.AddMergedHead(objChange)
	if err != nil {
		panic(err)
	}

	mode := Append
	if content.IsSnapshot {
		mode = Rebuild
	}

	res = AddResult{
		OldHeads: oldHeads,
		Heads:    []string{objChange.Id},
		Added:    added,
		Mode:     mode,
	}
	log.With("treeId", ot.id).With("head", objChange.Id).
		Debug("finished adding content")
	return
}

func (ot *objectTree) UnpackChange(raw *treechangeproto.RawTreeChangeWithId) (data []byte, err error) {
	if ot.isDeleted {
		err = ErrDeleted
		return
	}
	unmarshalled, err := ot.changeBuilder.Unmarshall(raw, true)
	if err != nil {
		return
	}
	data = unmarshalled.Data
	return
}

func (ot *objectTree) PrepareChange(content SignableChangeContent) (res *treechangeproto.RawTreeChangeWithId, err error) {
	if ot.isDeleted {
		err = ErrDeleted
		return
	}
	payload, err := ot.prepareBuilderContent(content)
	if err != nil {
		return
	}
	_, res, err = ot.changeBuilder.Build(payload)
	return
}

func (ot *objectTree) prepareBuilderContent(content SignableChangeContent) (cnt BuilderContent, err error) {
	ot.aclList.RLock()
	defer ot.aclList.RUnlock()

	var (
		state     = ot.aclList.AclState() // special method for own keys
		readKey   crypto.SymKey
		pubKey    = content.Key.GetPublic()
		readKeyId string
	)
	if !state.Permissions(pubKey).CanWrite() {
		err = list.ErrInsufficientPermissions
		return
	}

	if content.ShouldBeEncrypted {
		err = ot.readKeysFromAclState(state)
		if err != nil {
			return
		}
		readKeyId = state.CurrentReadKeyId()
		if ot.currentReadKey == nil {
			err = ErrMissingKey
			return
		}
		readKey = ot.currentReadKey
	}
	timestamp := content.Timestamp
	if timestamp <= 0 {
		timestamp = time.Now().Unix()
	}
	cnt = BuilderContent{
		TreeHeadIds:    ot.tree.Heads(),
		AclHeadId:      ot.aclList.Head().Id,
		SnapshotBaseId: ot.tree.RootId(),
		ReadKeyId:      readKeyId,
		IsSnapshot:     content.IsSnapshot,
		Unencrypted:    !content.ShouldBeEncrypted,
		PrivKey:        content.Key,
		ReadKey:        readKey,
		Content:        content.Data,
		DataType:       content.DataType,
		Timestamp:      timestamp,
	}
	return
}

func (ot *objectTree) AddRawChangesWithUpdater(ctx context.Context, changes RawChangesPayload, updater Updater) (addResult AddResult, err error) {
	if ot.isDeleted {
		err = ErrDeleted
		return
	}
	ot.logUseWhenUnlocked()
	lastHeadId := ot.tree.lastIteratedHeadId
	addResult, err = ot.addChangesToTree(ctx, changes)
	if err != nil {
		return
	}

	// reducing tree if we have new roots
	err = ot.flusher.FlushAfterBuild(ot)
	if err != nil {
		return
	}

	// that means that we removed the ids while reducing
	if _, exists := ot.tree.attached[lastHeadId]; !exists {
		addResult.Mode = Rebuild
	}

	rollback := func() {
		_, rebuildErr := ot.rebuildFromStorage(nil, nil, nil)
		if rebuildErr != nil {
			log.Error("failed to rebuild after adding to storage", zap.Strings("heads", ot.Heads()), zap.Error(rebuildErr))
		}
	}

	if updater != nil && !ot.deferredUpdater {
		err = updater(ot, addResult.Mode)
		if err != nil {
			rollback()
			return
		}
	}

	err = ot.storage.AddAll(ctx, addResult.Added, addResult.Heads, ot.tree.RootId())
	if err != nil {
		rollback()
		return
	}

	if updater != nil && ot.deferredUpdater {
		err = updater(ot, addResult.Mode)
		if err != nil {
			return
		}
	}
	ot.flusher.Flush(ot)
	return
}

func (ot *objectTree) AddRawChanges(ctx context.Context, changesPayload RawChangesPayload) (addResult AddResult, err error) {
	return ot.AddRawChangesWithUpdater(ctx, changesPayload, nil)
}

func (ot *objectTree) addChangesToTree(ctx context.Context, changesPayload RawChangesPayload) (addResult AddResult, err error) {
	// resetting buffers
	ot.newChangesBuf = ot.newChangesBuf[:0]
	ot.difSnapshotBuf = ot.difSnapshotBuf[:0]
	ot.newSnapshotsBuf = ot.newSnapshotsBuf[:0]

	headsCopy := func(heads []string) []string {
		newHeads := make([]string, 0, len(ot.tree.Heads()))
		newHeads = append(newHeads, heads...)
		return newHeads
	}

	var (
		// this will be returned to client, so we shouldn't use buffer here
		prevHeadsCopy  = headsCopy(ot.tree.Heads())
		lastIteratedId = ot.tree.lastIteratedHeadId
	)

	// filtering changes, verifying and unmarshalling them
	for _, ch := range changesPayload.RawChanges {
		// not unmarshalling the changes if they were already added either as unattached or attached
		if _, exists := ot.tree.attached[ch.Id]; exists {
			continue
		}

		var change *Change
		if unAttached, exists := ot.tree.unAttached[ch.Id]; exists {
			change = unAttached
		} else {
			change, err = ot.changeBuilder.Unmarshall(ch, true)
			if err != nil {
				return
			}
		}
		change.rawChange = ch

		if change.IsSnapshot {
			ot.newSnapshotsBuf = append(ot.newSnapshotsBuf, change)
		}
		ot.newChangesBuf = append(ot.newChangesBuf, change)
	}

	// if no new changes, then returning
	if len(ot.newChangesBuf) == 0 {
		addResult = AddResult{
			OldHeads: prevHeadsCopy,
			Heads:    prevHeadsCopy,
			Mode:     Nothing,
		}
		return
	}

	var (
		filteredHeads = false
		headsToUse    = changesPayload.NewHeads
	)
	// if our validator provides filtering mechanism then we use it
	filteredHeads, ot.newChangesBuf, ot.newSnapshotsBuf = ot.validator.FilterChanges(ot.aclList, ot.newChangesBuf, ot.newSnapshotsBuf)
	if filteredHeads {
		// if we filtered some of the heads, then we don't know which heads to use
		headsToUse = []string{}
	}
	rollback := func(changes []*Change) {
		var visited []*Change
		for _, ch := range changes {
			if ex, exists := ot.tree.attached[ch.Id]; exists {
				ex.visited = true
				visited = append(visited, ex)
				delete(ot.tree.attached, ch.Id)
			}
		}
		for _, ch := range ot.tree.attached {
			// deleting all visited changes from next
			ch.Next = slice.DiscardFromSlice(ch.Next, func(change *Change) bool {
				return change.visited
			})
		}
		// doing this just in case
		for _, ch := range visited {
			ch.visited = false
		}
		ot.tree.headIds = headsCopy(prevHeadsCopy)
		ot.tree.lastIteratedHeadId = lastIteratedId
	}

	// checks if we need to go to database
	snapshotNotInTree := func(ch *Change) (bool, error) {
		if ch.SnapshotId == ot.tree.RootId() {
			return false, nil
		}
		if oldSn, ok := ot.tree.attached[ch.SnapshotId]; ok {
			if !oldSn.IsSnapshot {
				return false, ErrHasInvalidChanges
			}
		}
		for _, sn := range ot.newSnapshotsBuf {
			// if change refers to newly received snapshot
			if ch.SnapshotId == sn.Id {
				return false, nil
			}
		}
		return true, nil
	}

	shouldRebuildFromStorage := false
	// checking if we have some changes with different snapshot and then rebuilding
	for _, ch := range ot.newChangesBuf {
		var notInTree bool
		notInTree, err = snapshotNotInTree(ch)
		if err != nil {
			return
		}
		if notInTree {
			shouldRebuildFromStorage = true
			break
		}
	}
	log := log.With(zap.String("treeId", ot.id))
	if shouldRebuildFromStorage {
		var added []*Change
		added, err = ot.rebuildFromStorage(headsToUse, changesPayload.SnapshotPath, ot.newChangesBuf)
		if err != nil {
			log.Error("failed to rebuild with new heads", zap.Strings("headsToUse", headsToUse), zap.Error(err))
			// rebuilding without new changes
			_, rebuildErr := ot.rebuildFromStorage(nil, nil, nil)
			if rebuildErr != nil {
				log.Error("failed to rebuild from storage", zap.Strings("heads", ot.Heads()), zap.Error(rebuildErr))
			}
			return
		}
		addResult, err = ot.createAddResult(prevHeadsCopy, Rebuild, added)
		if err != nil {
			log.Error("failed to create add result", zap.Strings("headsToUse", headsToUse), zap.Error(err))
			// that means that some unattached changes were somehow corrupted in memory
			// this shouldn't happen but if that happens, then rebuilding from storage
			_, rebuildErr := ot.rebuildFromStorage(nil, nil, nil)
			if rebuildErr != nil {
				log.Error("failed to rebuild after add result", zap.Strings("heads", ot.Heads()), zap.Error(rebuildErr))
			}
		}
		return
	}

	// normal mode of operation, where we don't need to rebuild from database
	mode, treeChangesAdded := ot.tree.Add(ot.newChangesBuf...)
	switch mode {
	case Nothing:
		addResult = AddResult{
			OldHeads: prevHeadsCopy,
			Heads:    prevHeadsCopy,
			Mode:     mode,
		}
		return

	default:
		// we need to validate only newly added changes
		err = ot.validateTree(treeChangesAdded)
		if err != nil {
			rollback(treeChangesAdded)
			err = fmt.Errorf("%w: %w", ErrHasInvalidChanges, err)
			return
		}
		addResult, err = ot.createAddResult(prevHeadsCopy, mode, treeChangesAdded)
		if err != nil {
			// that means that some unattached changes were somehow corrupted in memory
			// this shouldn't happen but if that happens, then rebuilding from storage
			rollback(treeChangesAdded)
			_, rebuildErr := ot.rebuildFromStorage(nil, nil, nil)
			if rebuildErr != nil {
				log.Error("failed to rebuild after add result (add to tree)", zap.Strings("heads", ot.Heads()), zap.Error(rebuildErr))
			}
			return
		}
		return
	}
}

func (ot *objectTree) createAddResult(oldHeads []string, mode Mode, changes []*Change) (addResult AddResult, err error) {
	newHeads := make([]string, 0, len(ot.tree.Heads()))
	newHeads = append(newHeads, ot.tree.Heads()...)
	var added []StorageChange
	for _, ch := range changes {
		rawChange := ch.rawChange
		ot.flusher.MarkNewChange(ch)
		added = append(added, StorageChange{
			RawChange:       rawChange.RawChange,
			PrevIds:         ch.PreviousIds,
			Id:              ch.Id,
			SnapshotCounter: ch.SnapshotCounter,
			SnapshotId:      ch.SnapshotId,
			OrderId:         ch.OrderId,
			ChangeSize:      len(rawChange.RawChange),
		})
		ch.rawChange = nil
	}
	addResult = AddResult{
		OldHeads: oldHeads,
		Heads:    newHeads,
		Added:    added,
		Mode:     mode,
	}
	return
}

func (ot *objectTree) IterateRoot(convert ChangeConvertFunc, iterate ChangeIterateFunc) (err error) {
	return ot.IterateFrom(ot.tree.RootId(), convert, iterate)
}

func (ot *objectTree) IterateFrom(id string, convert ChangeConvertFunc, iterate ChangeIterateFunc) (err error) {
	if ot.isDeleted {
		err = ErrDeleted
		return
	}
	if convert == nil {
		ot.tree.IterateSkip(id, iterate)
		return
	}
	var buf []byte
	decrypt := func(c *Change) (decrypted []byte, err error) {
		// the change is not encrypted
		if c.ReadKeyId == "" {
			decrypted = c.Data
			return
		}
		readKey, exists := ot.keys[c.ReadKeyId]
		if !exists {
			err = list.ErrNoReadKey
			return
		}
		if c.Data == nil {
			err = fmt.Errorf("no data in change %s", c.Id)
			return
		}
		buf, err = readKey.DecryptReuse(buf, c.Data)
		decrypted = buf
		return
	}

	ot.tree.IterateSkip(id, func(c *Change) (isContinue bool) {
		var model any
		// if already saved as a model
		if c.Model != nil {
			return iterate(c)
		}
		// if this is a root change
		if c.Id == ot.id {
			return iterate(c)
		}

		decrypted, decErr := decrypt(c)
		if decErr != nil {
			err = decErr
			return false
		}

		model, err = convert(c, decrypted)
		if err != nil {
			return false
		}

		c.Model = model
		// delete data because it just wastes memory
		c.Data = nil
		return iterate(c)
	})
	return
}

func (ot *objectTree) IterateAfterAddSeq(ctx context.Context, addSeq uint64, convert ChangeConvertFunc, iterate ChangeIterateFunc) (err error) {
	if ot.isDeleted {
		return ErrDeleted
	}
	var buf []byte
	return ot.storage.GetAfterAddSeq(ctx, addSeq, func(ctx context.Context, sc StorageChange) (bool, error) {
		raw := sc.RawTreeChangeWithId()
		ch, uErr := ot.changeBuilder.Unmarshall(raw, false)
		if uErr != nil {
			return false, uErr
		}
		ch.OrderId = sc.OrderId
		ch.SnapshotCounter = sc.SnapshotCounter
		ch.AddSeq = sc.AddSeq

		if convert != nil && ch.Id != ot.id {
			if ch.ReadKeyId != "" {
				readKey, exists := ot.keys[ch.ReadKeyId]
				if !exists {
					return false, list.ErrNoReadKey
				}
				if ch.Data == nil {
					return false, fmt.Errorf("no data in change %s", ch.Id)
				}
				buf, uErr = readKey.DecryptReuse(buf, ch.Data)
				if uErr != nil {
					return false, uErr
				}
			} else {
				buf = ch.Data
			}
			model, cErr := convert(ch, buf)
			if cErr != nil {
				return false, cErr
			}
			ch.Model = model
			ch.Data = nil
		}
		return iterate(ch), nil
	})
}

func (ot *objectTree) HasChanges(chs ...string) bool {
	if ot.isDeleted {
		return false
	}
	for _, ch := range chs {
		if _, attachedExists := ot.tree.attached[ch]; !attachedExists {
			return false
		}
	}
	return true
}

func (ot *objectTree) Heads() []string {
	return ot.tree.Heads()
}

func (ot *objectTree) Root() *Change {
	return ot.tree.Root()
}

func (ot *objectTree) TryClose(objectTTL time.Duration) (bool, error) {
	return true, ot.Close()
}

func (ot *objectTree) Close() error {
	return ot.storage.Close()
}

func (ot *objectTree) Delete() error {
	if ot.isDeleted {
		return nil
	}
	ot.isDeleted = true
	return ot.storage.Delete(context.Background())
}

func (ot *objectTree) SnapshotPath() ([]string, error) {
	if ot.isDeleted {
		return nil, ErrDeleted
	}
	if ot.snapshotPathIsActual() {
		return ot.snapshotPath, nil
	}

	var path []string
	// TODO: think that the user may have not all of the snapshots locally
	currentSnapshotId := ot.tree.RootId()
	for currentSnapshotId != "" {
		sn, err := ot.storage.Get(context.Background(), currentSnapshotId)
		if err != nil {
			return nil, fmt.Errorf("failed to get snapshot %s: %w", currentSnapshotId, err)
		}
		path = append(path, currentSnapshotId)
		currentSnapshotId = sn.SnapshotId
	}
	ot.snapshotPath = path
	return path, nil
}

func (ot *objectTree) ChangesAfterCommonSnapshotLoader(theirPath, theirHeads []string) (LoadIterator, error) {
	if ot.isDeleted {
		return nil, ErrDeleted
	}
	var (
		needFullDocument = len(theirPath) == 0
		ourPath          []string
		// by default returning everything we have from start
		commonSnapshot string
		err            error
	)
	ourPath, err = ot.SnapshotPath()
	if err != nil {
		return nil, fmt.Errorf("failed to get snapshot path: %w", err)
	}
	commonSnapshot = ourPath[len(ourPath)-1]
	// if this is non-empty request
	if !needFullDocument {
		commonSnapshot, err = commonSnapshotForTwoPaths(ourPath, theirPath)
		if err != nil {
			return nil, err
		}
	}

	iter := newLoadIterator(ot.rawRoot, ourPath, ot.storage, ot.changeBuilder)
	err = iter.load(commonSnapshot, ot.tree.headIds, theirHeads)
	if err != nil {
		return nil, err
	}
	return iter, nil
}

// this is a helper function to be used in testing
func (ot *objectTree) changesAfterCommonSnapshot(theirPath, theirHeads []string) ([]*treechangeproto.RawTreeChangeWithId, error) {
	loader, err := ot.ChangesAfterCommonSnapshotLoader(theirPath, theirHeads)
	if err != nil {
		return nil, err
	}
	res, err := loader.NextBatch(10 * 1024 * 1024)
	if err != nil {
		return nil, err
	}
	return res.Batch, nil
}

func (ot *objectTree) snapshotPathIsActual() bool {
	return len(ot.snapshotPath) != 0 && ot.snapshotPath[0] == ot.tree.RootId()
}

func (ot *objectTree) validateTree(newChanges []*Change) error {
	ot.aclList.RLock()
	defer ot.aclList.RUnlock()
	state := ot.aclList.AclState()

	err := ot.readKeysFromAclState(state)
	if err != nil {
		return err
	}
	if len(newChanges) == 0 {
		return ot.validator.ValidateFullTree(ot.tree, ot.aclList)
	}

	return ot.validator.ValidateNewChanges(ot.tree, ot.aclList, newChanges)
}

func (ot *objectTree) readKeysFromAclState(state *list.AclState) (err error) {
	// just not to take lock many times, updating the key map from aclList
	if len(ot.keys) == len(state.Keys()) {
		return nil
	}
	// if we can't read the keys anyway
	if state.AccountKey() == nil || !state.HadReadPermissions(state.AccountKey().GetPublic()) {
		return nil
	}
	deriver := crypto.NewKeyDeriver(fmt.Sprintf(crypto.AnysyncTreePath, ot.id))
	for key, value := range state.Keys() {
		if _, exists := ot.keys[key]; exists {
			continue
		}
		if value.ReadKey == nil {
			continue
		}
		raw, err := value.ReadKey.Raw()
		if err != nil {
			return err
		}
		treeKey, err := deriver.DeriveKey(raw)
		if err != nil {
			return err
		}
		ot.keys[key] = treeKey
	}
	curKeyId := state.CurrentReadKeyId()
	if derived, ok := ot.keys[curKeyId]; ok {
		ot.currentReadKey = derived
		return nil
	}
	// Fallback: derive if not in map (e.g., ReadKey was nil and skipped in the loop above)
	curKey, err := state.CurrentReadKey()
	if err != nil {
		return err
	}
	if curKey == nil {
		return nil
	}
	ot.currentReadKey, err = deriveTreeKey(curKey, ot.id)
	return err
}

func (ot *objectTree) Debug(parser DescriptionParser) (DebugInfo, error) {
	return objectTreeDebug{}.debugInfo(ot, parser)
}

package objecttree

import (
	"context"
	"fmt"
	"sync/atomic"

	anystore "github.com/anyproto/any-store"

	"github.com/anyproto/any-sync/commonspace/headsync/headstorage"
	"github.com/anyproto/any-sync/commonspace/object/acl/list"
	"github.com/anyproto/any-sync/commonspace/object/tree/treestorage"
	"github.com/anyproto/any-sync/util/slice"
)

type TreeStorageCreator interface {
	CreateTreeStorage(ctx context.Context, payload treestorage.TreeStorageCreatePayload) (Storage, error)
	CreateStorageWithDeferredCreation(ctx context.Context, payload treestorage.TreeStorageCreatePayload) (Storage, error)
}

type tempTreeStorageCreator struct {
	store anystore.DB
}

// noopAddSeq is a zero-valued counter for ephemeral validation storages
// that don't participate in incremental sync.
var noopAddSeq atomic.Uint64

func (t *tempTreeStorageCreator) CreateStorageWithDeferredCreation(ctx context.Context, payload treestorage.TreeStorageCreatePayload) (Storage, error) {
	headStorage, err := headstorage.New(ctx, t.store)
	if err != nil {
		return nil, err
	}
	st, err := CreateStorageWithDeferredCreation(ctx, payload.RootRawChange, headStorage, t.store)
	if err != nil {
		return nil, err
	}
	st.(*storageDeferredCreation).SetAddSeq(&noopAddSeq)
	return st, nil
}

func (t *tempTreeStorageCreator) CreateTreeStorage(ctx context.Context, payload treestorage.TreeStorageCreatePayload) (Storage, error) {
	headStorage, err := headstorage.New(ctx, t.store)
	if err != nil {
		return nil, err
	}
	st, err := CreateStorage(ctx, payload.RootRawChange, headStorage, t.store)
	if err != nil {
		return nil, err
	}
	st.(*storage).SetAddSeq(&noopAddSeq)
	return st, nil
}

type ValidatorFunc func(payload treestorage.TreeStorageCreatePayload, storageCreator TreeStorageCreator, aclList list.AclList) (ret ObjectTree, err error)

type ObjectTreeValidator interface {
	// ValidateFullTree should always be entered while holding a read lock on AclList
	ValidateFullTree(tree *Tree, aclList list.AclList) error
	// ValidateNewChanges should always be entered while holding a read lock on AclList
	ValidateNewChanges(tree *Tree, aclList list.AclList, newChanges []*Change) error
	FilterChanges(aclList list.AclList, changes []*Change, snapshots []*Change) (filteredHeads bool, filtered, filteredSnapshots []*Change)
}

type noOpTreeValidator struct {
	filterFunc func(ch *Change) bool
	fail       bool
}

func (n *noOpTreeValidator) ValidateFullTree(tree *Tree, aclList list.AclList) error {
	if n.fail {
		return fmt.Errorf("failed")
	}
	return nil
}

func (n *noOpTreeValidator) ValidateNewChanges(tree *Tree, aclList list.AclList, newChanges []*Change) error {
	if n.fail {
		return fmt.Errorf("failed")
	}
	return nil
}

func (n *noOpTreeValidator) FilterChanges(aclList list.AclList, changes []*Change, snapshots []*Change) (filteredHeads bool, filtered, filteredSnapshots []*Change) {
	if n.filterFunc == nil {
		return false, changes, snapshots
	}
	for _, c := range changes {
		// only taking changes which we can read
		if n.filterFunc(c) {
			filtered = append(filtered, c)
			if c.IsSnapshot {
				filteredSnapshots = append(filteredSnapshots, c)
			}
		} else {
			filteredHeads = true
		}
	}
	return
}

type objectTreeValidator struct {
	validateKeys     bool
	shouldFilter     bool
	contentValidator func(c *Change, aclList list.AclList) error
}

func newTreeValidator(validateKeys bool, filterChanges bool) ObjectTreeValidator {
	return &objectTreeValidator{
		validateKeys: validateKeys,
		shouldFilter: filterChanges,
	}
}

func NewTreeValidatorWithContentCheck(
	validateKeys, filterChanges bool,
	check func(*Change, list.AclList) error,
) ObjectTreeValidator {
	return &objectTreeValidator{
		validateKeys:     validateKeys,
		shouldFilter:     filterChanges,
		contentValidator: check,
	}
}

func (v *objectTreeValidator) ValidateFullTree(tree *Tree, aclList list.AclList) (err error) {
	tree.IterateSkip(tree.RootId(), func(c *Change) (isContinue bool) {
		err = v.validateChange(tree, aclList, c)
		return err == nil
	})
	return err
}

func (v *objectTreeValidator) ValidateNewChanges(tree *Tree, aclList list.AclList, newChanges []*Change) (err error) {
	for _, c := range newChanges {
		err = v.validateChange(tree, aclList, c)
		if err != nil {
			return
		}
	}
	return
}

func (v *objectTreeValidator) FilterChanges(aclList list.AclList, changes []*Change, snapshots []*Change) (filteredHeads bool, filtered, filteredSnapshots []*Change) {
	if !v.shouldFilter {
		return false, changes, snapshots
	}
	aclList.RLock()
	defer aclList.RUnlock()
	state := aclList.AclState()
	for _, c := range changes {
		// this has to be a root
		if c.PreviousIds == nil {
			filtered = append(filtered, c)
			filteredSnapshots = append(filteredSnapshots, c)
			continue
		}
		// only taking changes which we can read and for which we have acl heads
		if keys, exists := state.Keys()[c.ReadKeyId]; aclList.HasHead(c.AclHeadId) && exists && keys.ReadKey != nil {
			filtered = append(filtered, c)
			if c.IsSnapshot {
				filteredSnapshots = append(filteredSnapshots, c)
			}
			continue
		}
		// if we filtered at least one change this can be the change between heads and other changes
		// thus we cannot use heads
		filteredHeads = true
	}
	return
}

func (v *objectTreeValidator) validateChange(tree *Tree, aclList list.AclList, c *Change) (err error) {
	var (
		perms list.AclPermissions
		state = aclList.AclState()
	)
	if c.IsDerived {
		return nil
	}
	// checking if the user could write
	perms, err = state.PermissionsAtRecord(c.AclHeadId, c.Identity)
	if err != nil {
		return
	}
	if !perms.CanWrite() {
		err = list.ErrInsufficientPermissions
		return
	}
	if c.Id == tree.RootId() {
		return
	}
	if v.validateKeys {
		keys, exists := state.Keys()[c.ReadKeyId]
		if !exists || keys.ReadKey == nil {
			return list.ErrNoReadKey
		}
	}

	if v.contentValidator != nil {
		if err = v.contentValidator(c, aclList); err != nil {
			return
		}
	}

	// checking if the change refers to later acl heads than its previous ids
	for _, id := range c.PreviousIds {
		prevChange := tree.attached[id]
		if prevChange.AclHeadId == c.AclHeadId {
			continue
		}
		if prevChange.IsDerived {
			continue
		}
		var after bool
		after, err = aclList.IsAfter(c.AclHeadId, prevChange.AclHeadId)
		if err != nil {
			return
		}
		if !after {
			err = fmt.Errorf("current acl head id (%s) should be after each of the previous ones (%s)", c.AclHeadId, prevChange.AclHeadId)
			return
		}
	}
	return
}

func ValidateRawTreeDefault(payload treestorage.TreeStorageCreatePayload, storageCreator TreeStorageCreator, aclList list.AclList) (objTree ObjectTree, err error) {
	ctx := context.Background()
	treeStorage, err := storageCreator.CreateStorageWithDeferredCreation(ctx, treestorage.TreeStorageCreatePayload{
		RootRawChange: payload.RootRawChange,
		Heads:         []string{payload.RootRawChange.Id},
	})
	if err != nil {
		return
	}
	tree, err := BuildEmptyDataObjectTree(treeStorage, aclList)
	if err != nil {
		return
	}
	tree.Lock()
	defer tree.Unlock()
	res, err := tree.AddRawChanges(context.Background(), RawChangesPayload{
		NewHeads:   payload.Heads,
		RawChanges: payload.Changes,
	})
	if err != nil {
		return
	}
	if !slice.UnsortedEquals(res.Heads, payload.Heads) {
		return nil, fmt.Errorf("heads mismatch: %v != %v, %w", res.Heads, payload.Heads, ErrHasInvalidChanges)
	}
	// if tree has only one change we still should check if the snapshot id is same as root
	if IsEmptyDerivedTree(tree) {
		return nil, ErrDerived
	}
	return tree, nil
}

func ValidateFilterRawTree(payload treestorage.TreeStorageCreatePayload, storageCreator TreeStorageCreator, aclList list.AclList) (objTree ObjectTree, err error) {
	aclList.RLock()
	if !aclList.AclState().HadReadPermissions(aclList.AclState().Identity()) {
		aclList.RUnlock()
		return nil, list.ErrNoReadKey
	}
	aclList.RUnlock()
	ctx := context.Background()
	treeStorage, err := storageCreator.CreateStorageWithDeferredCreation(ctx, treestorage.TreeStorageCreatePayload{
		RootRawChange: payload.RootRawChange,
		Heads:         []string{payload.RootRawChange.Id},
	})
	if err != nil {
		return
	}
	tree, err := BuildEmptyDataKeyFilterableObjectTree(treeStorage, aclList)
	if err != nil {
		return
	}
	tree.Lock()
	defer tree.Unlock()
	_, err = tree.AddRawChanges(context.Background(), RawChangesPayload{
		NewHeads:   payload.Heads,
		RawChanges: payload.Changes,
	})
	if err != nil {
		return
	}
	if IsEmptyTree(tree) {
		return nil, ErrNoChangeInTree
	}
	return tree, nil
}

func ValidateRawTree(payload treestorage.TreeStorageCreatePayload, aclList list.AclList, store anystore.DB) (err error) {
	_, err = ValidateRawTreeDefault(payload, &tempTreeStorageCreator{store: store}, aclList)
	return
}

commonspace/object/tree/objecttree/stora.text:
package objecttree

import (
	"context"
	"errors"
	"fmt"
	"sync/atomic"
	"time"

	anystore "github.com/anyproto/any-store"
	"github.com/anyproto/any-store/anyenc"
	"github.com/anyproto/any-store/query"

	"github.com/anyproto/any-sync/commonspace/headsync/headstorage"
	"github.com/anyproto/any-sync/commonspace/object/tree/treechangeproto"
	"github.com/anyproto/any-sync/commonspace/object/tree/treestorage"
	"github.com/anyproto/any-sync/util/crypto"
	"github.com/anyproto/any-sync/util/storeutil"
)

const (
	OrderKey           = "o"
	idKey              = "id"
	rawChangeKey       = "r"
	SnapshotCounterKey = "sc"
	ChangeSizeKey      = "sz"
	snapshotIdKey      = "i"
	addedKey           = "a"
	prevIdsKey         = "p"
	TreeKey            = "t"
	CollName           = "changes"
	AddSeqKey          = "q"
)

type StorageChange struct {
	RawChange       []byte
	PrevIds         []string
	Id              string
	SnapshotCounter int
	SnapshotId      string
	OrderId         string
	ChangeSize      int
	TreeId          string
	// AddSeq is a per-space monotonically growing sequence assigned on insert.
	// Used to bridge space storage and CRDT storage: a CRDT processor tracks
	// the last applied seq and fetches only newer changes via GetAfterAddSeq.
	// Gaps are expected (e.g. rolled-back transactions) and safe — only the
	// guarantee of monotonic growth matters. Local to this peer, not synced.
	AddSeq uint64
}

func (c StorageChange) RawTreeChangeWithId() *treechangeproto.RawTreeChangeWithId {
	return &treechangeproto.RawTreeChangeWithId{
		RawChange: c.RawChange,
		Id:        c.Id,
	}
}

type StorageIterator = func(ctx context.Context, change StorageChange) (shouldContinue bool, err error)

type Storage interface {
	Id() string
	Root(ctx context.Context) (StorageChange, error)
	Heads(ctx context.Context) ([]string, error)
	CommonSnapshot(ctx context.Context) (string, error)
	Has(ctx context.Context, id string) (bool, error)
	Get(ctx context.Context, id string) (StorageChange, error)
	GetAfterOrder(ctx context.Context, orderId string, iter StorageIterator) error
	// GetAfterAddSeq iterates changes with AddSeq strictly greater than the given value.
	// Enables incremental sync: a consumer remembers its last processed seq and
	// fetches only changes added since then, without rescanning the full tree.
	GetAfterAddSeq(ctx context.Context, addSeq uint64, iter StorageIterator) error
	AddAll(ctx context.Context, changes []StorageChange, heads []string, commonSnapshot string) error
	AddAllNoError(ctx context.Context, changes []StorageChange, heads []string, commonSnapshot string) error
	Delete(ctx context.Context) error
	Close() error
}

type storage struct {
	id          string
	store       anystore.DB
	headStorage headstorage.HeadStorage
	changesColl anystore.Collection
	arena       *anyenc.Arena
	parser      *anyenc.Parser
	root        StorageChange
	addSeq      *atomic.Uint64
}

var (
	StorageChangeBuilder = NewChangeBuilder
	// Deprecated: no longer returned; kept for compatibility.
	ErrParentNotFound = errors.New("parent object not found")
	ErrDerivedParent  = errors.New("derived object cannot be a parent")
)

func CreateStorage(ctx context.Context, root *treechangeproto.RawTreeChangeWithId, headStorage headstorage.HeadStorage, store anystore.DB) (Storage, error) {
	tx, err := store.WriteTx(ctx)
	if err != nil {
		return nil, err
	}
	storage, err := CreateStorageTx(tx.Context(), root, headStorage, store)
	if err != nil {
		tx.Rollback()
		return nil, err
	}
	return storage, tx.Commit()
}

func CreateStorageTx(ctx context.Context, root *treechangeproto.RawTreeChangeWithId, headStorage headstorage.HeadStorage, store anystore.DB) (Storage, error) {
	st := &storage{
		id:          root.Id,
		store:       store,
		headStorage: headStorage,
	}
	builder := StorageChangeBuilder(crypto.NewKeyStorage(), root)
	unmarshalled, err := builder.Unmarshall(root, true)
	if err != nil {
		return nil, err
	}
	firstOrder := lexId.Next("")
	stChange := StorageChange{
		RawChange:       root.RawChange,
		Id:              root.Id,
		SnapshotCounter: 1,
		SnapshotId:      "",
		OrderId:         firstOrder,
		TreeId:          root.Id,
		ChangeSize:      len(root.RawChange),
	}
	st.root = stChange
	changesColl, err := store.Collection(ctx, CollName)
	if err != nil {
		return nil, err
	}
	st.changesColl = changesColl
	st.arena = &anyenc.Arena{}
	st.parser = &anyenc.Parser{}
	defer st.arena.Reset()
	doc := newStorageChangeValue(stChange, st.arena)
	err = st.changesColl.Insert(ctx, doc)
	if err != nil {
		if errors.Is(err, anystore.ErrDocExists) {
			return nil, treestorage.ErrTreeExists
		}
		return nil, err
	}
	headsUpdate := headstorage.HeadsUpdate{
		Id:             root.Id,
		Heads:          []string{root.Id},
		CommonSnapshot: &root.Id,
		IsDerived:      &unmarshalled.IsDerived,
	}
	if unmarshalled.ParentId != "" {
		// The parent may arrive later or from another peer: the child is
		// stored now and the binding cascades either way (deletion walks
		// children by ParentId). A parent already gone takes the child
		// with it. "A derived object cannot be a parent" is enforced where
		// the child is created (objecttreebuilder.DeriveTree).
		headsUpdate.ParentId = &unmarshalled.ParentId
		parentEntry, parentErr := st.headStorage.GetEntry(ctx, unmarshalled.ParentId)
		switch {
		case parentErr == nil && parentEntry.DeletedStatus >= headstorage.DeletedStatusQueued:
			queued := headstorage.DeletedStatusQueued
			headsUpdate.DeletedStatus = &queued
		case parentErr != nil && !errors.Is(parentErr, anystore.ErrDocNotFound):
			return nil, parentErr
		}
	}
	err = st.headStorage.UpdateEntry(ctx, headsUpdate)
	if err != nil {
		return nil, err
	}
	return st, nil
}

func NewStorage(ctx context.Context, id string, headStorage headstorage.HeadStorage, store anystore.DB) (Storage, error) {
	st := &storage{
		id:          id,
		store:       store,
		headStorage: headStorage,
	}
	if _, err := headStorage.GetEntry(ctx, id); err != nil {
		if errors.Is(err, anystore.ErrDocNotFound) {
			return nil, treestorage.ErrUnknownTreeId
		}
		return nil, fmt.Errorf("failed to get head entry: %w", err)
	}
	changesColl, err := store.OpenCollection(ctx, CollName)
	if err != nil {
		return nil, fmt.Errorf("failed to open collection: %w", err)
	}
	st.changesColl = changesColl
	st.arena = &anyenc.Arena{}
	st.parser = &anyenc.Parser{}
	st.root, err = st.getWithoutParser(ctx, st.id)
	if err != nil {
		if errors.Is(err, anystore.ErrDocNotFound) {
			return nil, treestorage.ErrUnknownTreeId
		}
		return nil, err
	}
	return st, nil
}

func (s *storage) Heads(ctx context.Context) (res []string, err error) {
	headsEntry, err := s.headStorage.GetEntry(ctx, s.id)
	if err != nil {
		err = fmt.Errorf("failed to get heads entry: %w", err)
		return
	}
	return headsEntry.Heads, nil
}

func (s *storage) Has(ctx context.Context, id string) (bool, error) {
	_, err := s.changesColl.FindIdWithParser(ctx, s.parser, id)
	if err != nil {
		if errors.Is(err, anystore.ErrDocNotFound) {
			return false, nil
		}
		return false, err
	}
	return true, nil
}

func (s *storage) GetAfterOrder(ctx context.Context, orderId string, storageIter StorageIterator) error {
	// this method can be called without having a lock on a tree, so don't reuse any non-thread-safe parts
	filter := query.And{
		query.Key{Path: []string{OrderKey}, Filter: query.NewComp(query.CompOpGte, orderId)},
		query.Key{Path: []string{TreeKey}, Filter: query.NewComp(query.CompOpEq, s.id)},
	}
	qry := s.changesColl.Find(filter).Sort(OrderKey)
	iter, err := qry.Iter(ctx)
	if err != nil {
		return fmt.Errorf("find iter: %w", err)
	}
	defer iter.Close()

	for iter.Next() {
		doc, err := iter.Doc()
		if err != nil {
			return fmt.Errorf("doc not found: %w", err)
		}
		cont, err := storageIter(ctx, s.changeFromDoc(doc))
		if !cont {
			return err
		}
	}
	return nil
}

func (s *storage) GetAfterAddSeq(ctx context.Context, addSeq uint64, storageIter StorageIterator) error {
	filter := query.And{
		query.Key{Path: []string{AddSeqKey}, Filter: query.NewComp(query.CompOpGt, addSeq)},
		query.Key{Path: []string{TreeKey}, Filter: query.NewComp(query.CompOpEq, s.id)},
	}
	qry := s.changesColl.Find(filter).Sort(OrderKey)
	iter, err := qry.Iter(ctx)
	if err != nil {
		return fmt.Errorf("find iter: %w", err)
	}
	defer iter.Close()
	for iter.Next() {
		doc, err := iter.Doc()
		if err != nil {
			return fmt.Errorf("doc not found: %w", err)
		}
		cont, err := storageIter(ctx, s.changeFromDoc(doc))
		if !cont {
			return err
		}
	}
	return nil
}

func (s *storage) AddAll(ctx context.Context, changes []StorageChange, heads []string, commonSnapshot string) (err error) {
	arena := s.arena
	defer arena.Reset()
	tx, err := s.store.WriteTx(ctx)
	if err != nil {
		return fmt.Errorf("failed to create write tx: %w", err)
	}
	defer func() {
		if err != nil {
			tx.Rollback()
		} else {
			err = tx.Commit()
		}
	}()
	seq := s.addSeq.Add(1)
	for i := range changes {
		changes[i].AddSeq = seq
		changes[i].TreeId = s.id
		newVal := newStorageChangeValue(changes[i], arena)
		err = s.changesColl.Insert(tx.Context(), newVal)
		arena.Reset()
		if err != nil {
			return err
		}
	}
	err = s.headStorage.UpdateEntry(tx.Context(), headstorage.HeadsUpdate{
		Id:             s.id,
		Heads:          heads,
		CommonSnapshot: &commonSnapshot,
		LastAddSeq:     &seq,
	})
	return err
}

func (s *storage) AddAllNoError(ctx context.Context, changes []StorageChange, heads []string, commonSnapshot string) (err error) {
	arena := s.arena
	defer arena.Reset()
	tx, err := s.store.WriteTx(ctx)
	if err != nil {
		return fmt.Errorf("failed to create write tx: %w", err)
	}
	defer func() {
		if err != nil {
			tx.Rollback()
		} else {
			err = tx.Commit()
		}
	}()
	seq := s.addSeq.Add(1)
	for i := range changes {
		changes[i].AddSeq = seq
		changes[i].TreeId = s.id
		newVal := newStorageChangeValue(changes[i], arena)
		err = s.changesColl.Insert(tx.Context(), newVal)
		arena.Reset()
		if err != nil && !errors.Is(err, anystore.ErrDocExists) {
			return err
		}
	}
	err = s.headStorage.UpdateEntry(tx.Context(), headstorage.HeadsUpdate{
		Id:             s.id,
		Heads:          heads,
		CommonSnapshot: &commonSnapshot,
		LastAddSeq:     &seq,
	})
	return err
}

func (s *storage) Delete(ctx context.Context) error {
	tx, err := s.store.WriteTx(ctx)
	if err != nil {
		return fmt.Errorf("failed to create write tx: %w", err)
	}
	_, err = s.changesColl.Find(query.Key{Path: []string{TreeKey}, Filter: query.NewComp(query.CompOpEq, s.id)}).Delete(tx.Context())
	if err != nil {
		tx.Rollback()
		return err
	}
	return tx.Commit()
}

func (s *storage) Close() error {
	return s.changesColl.Close()
}

func (s *storage) SetAddSeq(seq *atomic.Uint64) {
	s.addSeq = seq
}

func (s *storage) Id() string {
	return s.id
}

func (s *storage) Root(ctx context.Context) (StorageChange, error) {
	return s.root, nil
}

func (s *storage) CommonSnapshot(ctx context.Context) (string, error) {
	// TODO: cache this in memory if needed
	entry, err := s.headStorage.GetEntry(ctx, s.id)
	if err != nil {
		return "", fmt.Errorf("failed to get head entry for common snapshot: %w", err)
	}
	return entry.CommonSnapshot, nil
}

func (s *storage) getWithoutParser(ctx context.Context, id string) (StorageChange, error) {
	// root will be reused outside the lock, so we shouldn't use parser for it
	doc, err := s.changesColl.FindId(ctx, id)
	if err != nil {
		return StorageChange{}, err
	}
	return s.changeFromDoc(doc), nil
}

func (s *storage) Get(ctx context.Context, id string) (StorageChange, error) {
	doc, err := s.changesColl.FindIdWithParser(ctx, s.parser, id)
	if err != nil {
		return StorageChange{}, err
	}
	return s.changeFromDoc(doc), nil
}

func (s *storage) changeFromDoc(doc anystore.Doc) StorageChange {
	return StorageChange{
		Id:              doc.Value().GetString(idKey),
		RawChange:       doc.Value().GetBytes(rawChangeKey),
		SnapshotId:      doc.Value().GetString(snapshotIdKey),
		OrderId:         doc.Value().GetString(OrderKey),
		ChangeSize:      doc.Value().GetInt(ChangeSizeKey),
		SnapshotCounter: doc.Value().GetInt(SnapshotCounterKey),
		PrevIds:         storeutil.StringsFromArrayValue(doc.Value(), prevIdsKey),
		AddSeq:          uint64(doc.Value().GetInt(AddSeqKey)),
	}
}

func newStorageChangeValue(ch StorageChange, arena *anyenc.Arena) *anyenc.Value {
	newVal := arena.NewObject()
	newVal.Set(OrderKey, arena.NewString(ch.OrderId))
	newVal.Set(rawChangeKey, arena.NewBinary(ch.RawChange))
	newVal.Set(SnapshotCounterKey, arena.NewNumberInt(ch.SnapshotCounter))
	newVal.Set(snapshotIdKey, arena.NewString(ch.SnapshotId))
	newVal.Set(ChangeSizeKey, arena.NewNumberInt(ch.ChangeSize))
	newVal.Set(idKey, arena.NewString(ch.Id))
	newVal.Set(TreeKey, arena.NewString(ch.TreeId))
	newVal.Set(addedKey, arena.NewNumberFloat64(float64(time.Now().Unix())))
	if len(ch.PrevIds) != 0 {
		newVal.Set(prevIdsKey, storeutil.NewStringArrayValue(ch.PrevIds, arena))
	}
	if ch.AddSeq > 0 {
		newVal.Set(AddSeqKey, arena.NewNumberInt(int(ch.AddSeq)))
	}
	return newVal
}

package objecttree

import (
	"context"
	"errors"
	"fmt"
	"sync/atomic"

	anystore "github.com/anyproto/any-store"
	"github.com/anyproto/any-sync/commonspace/headsync/headstorage"
	"github.com/anyproto/any-sync/commonspace/object/tree/treechangeproto"
	"github.com/anyproto/any-sync/commonspace/object/tree/treestorage"
)

type storageDeferredCreation struct {
	id string

	store       anystore.DB
	headStorage headstorage.HeadStorage
	addSeq      *atomic.Uint64

	storage Storage

	heads            []string
	root             StorageChange
	unmarshalledRoot *Change
}

// CreateStorageWithDeferredCreation defers actual creation of a storage until any call to updating methods (AddAll, Delete, etc.)
// The point is to create storage and add all changes in one transaction. We can't afford long transactions because of the single write connection.
// It returns ErrTreeExists if storage already exists.
func CreateStorageWithDeferredCreation(ctx context.Context, root *treechangeproto.RawTreeChangeWithId, headStorage headstorage.HeadStorage, store anystore.DB) (Storage, error) {
	firstOrder := lexId.Next("")
	stChange := StorageChange{
		RawChange:       root.RawChange,
		Id:              root.Id,
		SnapshotCounter: 1,
		SnapshotId:      "",
		OrderId:         firstOrder,
		TreeId:          root.Id,
		ChangeSize:      len(root.RawChange),
	}

	st := &storageDeferredCreation{
		id:          root.Id,
		store:       store,
		headStorage: headStorage,
		root:        stChange,
		heads:       []string{root.Id},
	}
	ok, err := st.isRootChangeStored(ctx)
	if err != nil {
		return nil, fmt.Errorf("check if storage exists: %w", err)
	}
	if ok {
		return nil, treestorage.ErrTreeExists
	}
	return st, nil
}

func (s *storageDeferredCreation) isRootChangeStored(ctx context.Context) (bool, error) {
	changesColl, err := s.store.OpenCollection(ctx, CollName)
	if errors.Is(err, anystore.ErrCollectionNotFound) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	_, err = changesColl.FindId(ctx, s.root.Id)
	if err == nil {
		return true, nil
	}
	if errors.Is(err, anystore.ErrDocNotFound) {
		return false, nil
	}
	return false, err
}

func (s *storageDeferredCreation) createStorage(ctx context.Context) error {
	st, err := CreateStorageTx(ctx, s.root.RawTreeChangeWithId(), s.headStorage, s.store)
	if err != nil {
		return fmt.Errorf("create storage: %w", err)
	}
	st.(*storage).SetAddSeq(s.addSeq)
	s.storage = st
	return nil
}

func (s *storageDeferredCreation) SetAddSeq(seq *atomic.Uint64) {
	s.addSeq = seq
	if s.storage != nil {
		s.storage.(*storage).SetAddSeq(seq)
	}
}

func (s *storageDeferredCreation) Id() string {
	return s.id
}

func (s *storageDeferredCreation) Root(ctx context.Context) (StorageChange, error) {
	return s.root, nil
}

func (s *storageDeferredCreation) Heads(ctx context.Context) ([]string, error) {
	if s.storage != nil {
		return s.storage.Heads(ctx)
	}
	return s.heads, nil
}

func (s *storageDeferredCreation) CommonSnapshot(ctx context.Context) (string, error) {
	if s.storage != nil {
		return s.storage.CommonSnapshot(ctx)
	}
	return s.id, nil
}

func (s *storageDeferredCreation) Has(ctx context.Context, id string) (bool, error) {
	if s.storage != nil {
		return s.storage.Has(ctx, id)
	}
	return id == s.id, nil
}

func (s *storageDeferredCreation) Get(ctx context.Context, id string) (StorageChange, error) {
	if s.storage != nil {
		return s.storage.Get(ctx, id)
	}
	return s.root, nil
}

func (s *storageDeferredCreation) GetAfterOrder(ctx context.Context, orderId string, iter StorageIterator) error {
	if s.storage != nil {
		return s.storage.GetAfterOrder(ctx, orderId, iter)
	}
	if orderId <= s.root.OrderId {
		_, err := iter(ctx, s.root)
		return err
	}
	return nil
}

func (s *storageDeferredCreation) GetAfterAddSeq(ctx context.Context, addSeq uint64, iter StorageIterator) error {
	if s.storage != nil {
		return s.storage.GetAfterAddSeq(ctx, addSeq, iter)
	}
	if s.root.AddSeq > addSeq {
		_, err := iter(ctx, s.root)
		return err
	}
	return nil
}

func (s *storageDeferredCreation) createStorageAndDoInTx(ctx context.Context, proc func(ctx context.Context) error) error {
	tx, err := s.store.WriteTx(ctx)
	if err != nil {
		return fmt.Errorf("write tx: %w", err)
	}
	defer tx.Rollback()

	err = s.createStorage(tx.Context())
	if err != nil {
		return fmt.Errorf("init storage: %w", err)
	}

	err = proc(tx.Context())
	if err != nil {
		return fmt.Errorf("add all: %w", err)
	}
	return tx.Commit()
}

func (s *storageDeferredCreation) AddAll(ctx context.Context, changes []StorageChange, heads []string, commonSnapshot string) error {
	if s.storage == nil {
		return s.createStorageAndDoInTx(ctx, func(ctx context.Context) error {
			return s.storage.AddAll(ctx, changes, heads, commonSnapshot)
		})
	}
	return s.storage.AddAll(ctx, changes, heads, commonSnapshot)
}

func (s *storageDeferredCreation) AddAllNoError(ctx context.Context, changes []StorageChange, heads []string, commonSnapshot string) error {
	if s.storage == nil {
		return s.createStorageAndDoInTx(ctx, func(ctx context.Context) error {
			return s.storage.AddAllNoError(ctx, changes, heads, commonSnapshot)
		})
	}
	return s.storage.AddAllNoError(ctx, changes, heads, commonSnapshot)
}

func (s *storageDeferredCreation) Delete(ctx context.Context) error {
	if s.storage == nil {
		return s.createStorageAndDoInTx(ctx, func(ctx context.Context) error {
			return s.storage.Delete(ctx)
		})
	}
	return s.storage.Delete(ctx)
}

func (s *storageDeferredCreation) Close() error {
	if s.storage != nil {
		return s.storage.Close()
	}
	return nil
}

commonspace/object/tree/objecttree/tree..text:
package objecttree

import (
	"bytes"
	"crypto/md5"
	"fmt"
	"sort"

	"github.com/anyproto/lexid"
	"go.uber.org/zap"

	"github.com/anyproto/any-sync/util/slice"
)

type Mode int

const (
	Append Mode = iota
	Rebuild
	Nothing
)

var lexId = lexid.Must(lexid.CharsAllNoEscape, 4, 100)

type Tree struct {
	root               *Change
	headIds            []string
	lastIteratedHeadId string
	// attached is a set of all Changes that have been successfully handled and added (attached) to the tree
	attached map[string]*Change
	// unAttached is a set of pending Changes that wait for all their dependencies (previous changes) to be attached to the tree
	unAttached map[string]*Change
	// waitList is a set of all changes that wait for a previous change with id as a key to be attached.
	// previous change id => list of dependent change ids
	waitList       map[string][]string
	invalidChanges map[string]struct{}
	possibleRoots  []*Change

	// bufs
	visitedBuf []*Change
	stackBuf   []*Change
	addedBuf   []*Change

	duplicateEvents int
}

func (t *Tree) RootId() string {
	if t.root != nil {
		return t.root.Id
	}
	return ""
}

func (t *Tree) Root() *Change {
	return t.root
}

func (t *Tree) AddFast(changes ...*Change) []*Change {
	if len(changes) == 0 {
		return nil
	}
	defer t.clearUnattached()
	t.addedBuf = t.addedBuf[:0]
	for _, c := range changes {
		// ignore existing
		if _, ok := t.attached[c.Id]; ok {
			continue
		} else if _, ok := t.unAttached[c.Id]; ok {
			continue
		}
		t.add(c)
	}
	t.updateHeads()
	return t.addedBuf
}

func (t *Tree) AddMergedHead(c *Change) error {
	// check that it was not inserted previously
	if _, ok := t.attached[c.Id]; ok {
		return fmt.Errorf("change already exists") // TODO: named error
	} else if _, ok := t.unAttached[c.Id]; ok {
		return fmt.Errorf("change already exists")
	}

	// check that it was attached after adding
	if !t.add(c) {
		return fmt.Errorf("change is not attached")
	}

	// check that previous heads have new change as next
	for _, prevHead := range t.headIds {
		head := t.attached[prevHead]
		if len(head.Next) != 1 || head.Next[0].Id != c.Id {
			return fmt.Errorf("this is not a new head")
		}
	}
	t.headIds = []string{c.Id}
	t.lastIteratedHeadId = c.Id
	return nil
}

func (t *Tree) clearUnattached() {
	t.unAttached = make(map[string]*Change)
}

func (t *Tree) Add(changes ...*Change) (mode Mode, added []*Change) {
	defer t.clearUnattached()
	t.addedBuf = t.addedBuf[:0]
	var (
		// this is previous head id which should have been iterated last
		lastIteratedHeadId = t.lastIteratedHeadId
		empty              = t.Len() == 0
	)
	for _, c := range changes {
		// ignore existing
		if _, ok := t.attached[c.Id]; ok {
			continue
		} else if _, ok := t.unAttached[c.Id]; ok {
			continue
		}
		t.add(c)
	}
	if len(t.addedBuf) == 0 {
		mode = Nothing
		return
	}
	t.updateHeads()
	added = t.addedBuf

	if empty {
		mode = Rebuild
		return
	}

	// mode is Append for cases when we can safely start iterating from lastIteratedHeadId to build state
	// the idea here is that if all new changes have lastIteratedHeadId as previous,
	// then according to topological sorting order they will be looked at later than lastIteratedHeadId
	//
	// one important consideration is that if some unattached changes were added to the tree
	// as a result of adding new changes, then each of these unattached changes
	// will also have at least one of new changes as ancestor
	// and that means they will also be iterated later than lastIteratedHeadId
	mode = Append
	t.dfsNext([]*Change{t.attached[lastIteratedHeadId]},
		func(_ *Change) (isContinue bool) {
			return true
		},
		func(_ []*Change) {
			// checking if some new changes were not visited
			for _, ch := range changes {
				// if the change was not added to the tree, then skipping
				if _, ok := t.attached[ch.Id]; !ok {
					continue
				}
				// if some new change was not visited,
				// then we can't start from lastIteratedHeadId,
				// we need to start from root, so Rebuild
				if !ch.visited {
					mode = Rebuild
					break
				}
			}
		})

	return
}

// RemoveInvalidChange removes all the changes that are descendants of id
func (t *Tree) RemoveInvalidChange(id string) {
	stack := []string{id}
	// removing all children of this id (either next or unattached)
	for len(stack) > 0 {
		var exists bool
		top := stack[len(stack)-1]
		stack = stack[:len(stack)-1]

		if _, exists = t.invalidChanges[top]; exists {
			continue
		}

		var rem *Change
		t.invalidChanges[top] = struct{}{}
		if rem, exists = t.unAttached[top]; exists {
			delete(t.unAttached, top)
			// TODO: delete waitlist, this can only help for memory/performance
		} else if rem, exists = t.attached[top]; exists {
			// remove from all prev changes
			for _, id := range rem.PreviousIds {
				prev, exists := t.attached[id]
				if !exists {
					continue
				}
				for i, next := range prev.Next {
					if next.Id == top {
						prev.Next[i] = nil
						prev.Next = append(prev.Next[:i], prev.Next[i+1:]...)
						break
					}
				}
			}
			delete(t.attached, top)
		}
		for _, el := range rem.Next {
			stack = append(stack, el.Id)
		}
	}
	t.updateHeads()
}

func (t *Tree) add(c *Change) bool {
	if c == nil {
		return false
	}

	if t.root == nil { // first element
		t.root = c
		if c.OrderId == "" {
			c.OrderId = lexId.Next("")
		}
		t.lastIteratedHeadId = t.root.Id
		t.attached = map[string]*Change{
			c.Id: c,
		}
		t.unAttached = make(map[string]*Change)
		t.waitList = make(map[string][]string)
		t.invalidChanges = make(map[string]struct{})
		t.possibleRoots = make([]*Change, 0, 10)
		t.addedBuf = append(t.addedBuf, c)
		return true
	}
	if len(c.PreviousIds) > 1 {
		sort.Strings(c.PreviousIds)
	}
	// attaching only if all prev ids are attached
	attach, remove := t.canAttachOrRemove(c, true)
	if attach {
		t.attach(c, true)
	} else if !remove {
		t.unAttached[c.Id] = c
	}
	return attach
}

// canAttachOrRemoves returns attach=true if all previous changes are already present in a tree.
// If some previous change is not yet in the tree and addToWait is true, then add the current change to the wait list for
// this previous change.
// TODO Research how `remove` flag is used
func (t *Tree) canAttachOrRemove(c *Change, addToWait bool) (attach, remove bool) {
	if c == nil {
		return false, false
	}
	attach = true
	for _, pid := range c.PreviousIds {
		if _, ok := t.attached[pid]; ok {
			continue
		}
		attach = false
		if addToWait {
			// updating wait list for either unseen or unAttached changes
			wl := t.waitList[pid]
			wl = append(wl, c.Id)
			t.waitList[pid] = wl
		}
	}
	if !attach {
		return
	}
	// we should also have snapshot of attached change inside tree
	_, ok := t.attached[c.SnapshotId]
	if !ok {
		log.Error("snapshot not found in tree", zap.String("id", c.Id), zap.String("snapshot", c.SnapshotId))
		return false, true
	}
	return true, false
}

func (t *Tree) attach(c *Change, newEl bool) {
	t.attached[c.Id] = c
	t.addedBuf = append(t.addedBuf, c)
	if !newEl {
		delete(t.unAttached, c.Id)
	}
	// Update snapshot counter. It could be 0 if it's the first snapshot of a tree
	if c.SnapshotCounter == 0 {
		t.possibleRoots = append(t.possibleRoots, c)
		c.SnapshotCounter = t.attached[c.SnapshotId].SnapshotCounter + 1
	}

	// add next to all prev changes
	for _, id := range c.PreviousIds {
		// prev id must already be attached if we attach this id, so we don't need to check if it exists
		prev := t.attached[id]
		c.Previous = append(c.Previous, prev)
		// appending c to next changes of all previous changes
		if len(prev.Next) == 0 || prev.Next[len(prev.Next)-1].Id <= c.Id {
			prev.Next = append(prev.Next, c)
		} else {
			// inserting in correct position, before the change which is greater or equal
			insertIdx := 0
			for idx, el := range prev.Next {
				if el.Id >= c.Id {
					insertIdx = idx
					break
				}
			}
			prev.Next = append(prev.Next[:insertIdx+1], prev.Next[insertIdx:]...)
			prev.Next[insertIdx] = c
		}
	}
	// TODO: as a future optimization we can actually sort next later after we finished building the tree

	// Check the wait list
	if waitIds, ok := t.waitList[c.Id]; ok {
		for _, wid := range waitIds {
			// next can only be in unAttached, because if next is attached then previous (we) are attached
			// which is obviously not true, because we are attaching previous only now
			next := t.unAttached[wid]
			attach, remove := t.canAttachOrRemove(next, false)
			if attach {
				// All previous changes are attached for a waiting change, so we can attach it now.
				t.attach(next, false)
			} else if remove {
				delete(t.unAttached, next.Id)
			}
			// If we can't still attach it, it means that we don't have all dependencies (previous changes) attached.
			// Just wait and eventually all previous changes should be added to the tree.
		}
		delete(t.waitList, c.Id)
	}
}

func (t *Tree) LeaveOnlyBefore(proposedHeads []string) {
	stack := make([]*Change, 0, len(proposedHeads))
	for _, headId := range proposedHeads {
		if head, ok := t.attached[headId]; ok {
			stack = append(stack, head)
		}
	}
	t.dfsPrev(stack, nil, func(ch *Change) (isContinue bool) {
		ch.visited = true
		return true
	}, func(changes []*Change) {
		for id, ch := range t.attached {
			if !ch.visited {
				delete(t.attached, id)
			}
		}
		for _, ch := range changes {
			ch.Next = slice.DiscardFromSlice(ch.Next, func(change *Change) bool {
				return !change.visited
			})
		}
	})
	t.updateHeads()
}

func (t *Tree) dfsPrev(stack []*Change, breakpoints []string, visit func(ch *Change) (isContinue bool), afterVisit func([]*Change)) {
	t.visitedBuf = t.visitedBuf[:0]

	// setting breakpoints as visited
	for _, breakpoint := range breakpoints {
		if ch, ok := t.attached[breakpoint]; ok {
			ch.visited = true
			t.visitedBuf = append(t.visitedBuf, ch)
		}
	}

	defer func() {
		if afterVisit != nil {
			afterVisit(t.visitedBuf)
		}
		for _, ch := range t.visitedBuf {
			ch.visited = false
		}
	}()

	for len(stack) > 0 {
		ch := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if ch.visited {
			continue
		}

		ch.visited = true
		t.visitedBuf = append(t.visitedBuf, ch)

		for _, prevCh := range ch.Previous {
			if !prevCh.visited {
				stack = append(stack, prevCh)
			}
		}
		if !visit(ch) {
			return
		}
	}
}

func (t *Tree) dfsNext(stack []*Change, visit func(ch *Change) (isContinue bool), afterVisit func([]*Change)) {
	t.visitedBuf = t.visitedBuf[:0]

	defer func() {
		if afterVisit != nil {
			afterVisit(t.visitedBuf)
		}
		for _, ch := range t.visitedBuf {
			ch.visited = false
		}
	}()

	for len(stack) > 0 {
		ch := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if ch.visited {
			continue
		}

		ch.visited = true
		t.visitedBuf = append(t.visitedBuf, ch)

		for _, next := range ch.Next {
			if !next.visited {
				stack = append(stack, next)
			}
		}
		if !visit(ch) {
			return
		}
	}
}

func (t *Tree) updateHeads() {
	var (
		newHeadIds []string
		it         = newIterator()
		buf        = it.makeIterBuffer(t.root)
		// root change should always have order id
		lastOrderIdx = len(buf) - 1
	)
	defer freeIterator(it)
	// using buffer directly to simplify iteration, and not iterate twice or save changes in separate slice
	for idx := len(buf) - 1; idx >= 0; idx-- {
		c := buf[idx]
		if c.OrderId != "" {
			// if there is a gap between order ids, then we need to fill it
			if lastOrderIdx-idx > 1 {
				prev := buf[lastOrderIdx].OrderId
				before := buf[idx].OrderId
				for i := lastOrderIdx - 1; i > idx; i-- {
					var err error
					buf[i].OrderId, err = lexId.NextBefore(prev, before)
					if err != nil {
						// TODO: this should never happen
						panic(fmt.Sprintf("failed to generate order id: %v", err))
					}
					prev = buf[i].OrderId
				}
			}
			lastOrderIdx = idx
		}
		if len(c.Next) == 0 {
			newHeadIds = append(newHeadIds, c.Id)
		}
	}
	// if there are some order ids left, then we need to fill them, but there are no max id for them,
	// they are strictly after the lastIteratedId
	if lastOrderIdx != 0 {
		prev := buf[lastOrderIdx].OrderId
		for i := lastOrderIdx - 1; i >= 0; i-- {
			buf[i].OrderId = lexId.Next(prev)
			prev = buf[i].OrderId
		}
	}

	t.headIds = newHeadIds
	// the lastIteratedHeadId is the id of the head which was iterated last according to the order
	t.lastIteratedHeadId = newHeadIds[len(newHeadIds)-1]
	// TODO: check why do we need sorting here
	sort.Strings(t.headIds)
}

func (t *Tree) iterate(start *Change, f func(c *Change) (isContinue bool)) {
	it := newIterator()
	defer freeIterator(it)
	it.iterate(start, f)
}

func (t *Tree) iterateSkip(start *Change, f func(c *Change) (isContinue bool)) {
	it := newIterator()
	defer freeIterator(it)
	it.iterateSkip(t.root, start, true, f)
}

func (t *Tree) IterateSkip(startId string, f func(c *Change) (isContinue bool)) {
	t.iterateSkip(t.attached[startId], f)
}

func (t *Tree) IterateBranching(startId string, f func(c *Change, branchLevel int) (isContinue bool)) {
	// branchLevel indicates the number of parallel branches
	var bc int
	t.iterate(t.attached[startId], func(c *Change) (isContinue bool) {
		if pl := len(c.PreviousIds); pl > 1 {
			bc -= pl - 1
		}
		bl := bc
		if nl := len(c.Next); nl > 1 {
			bc += nl - 1
		}
		return f(c, bl)
	})
}

func (t *Tree) Hash() string {
	h := md5.New()
	n := 0
	t.iterate(t.root, func(c *Change) (isContinue bool) {
		n++
		fmt.Fprintf(h, "-%s", c.Id)
		return true
	})
	return fmt.Sprintf("%d-%x", n, h.Sum(nil))
}

func (t *Tree) GetDuplicateEvents() int {
	return t.duplicateEvents
}

func (t *Tree) ResetDuplicateEvents() {
	t.duplicateEvents = 0
}

func (t *Tree) Len() int {
	return len(t.attached)
}

func (t *Tree) Heads() []string {
	return t.headIds
}

func (t *Tree) HeadsChanges() []*Change {
	var heads []*Change
	for _, head := range t.headIds {
		heads = append(heads, t.attached[head])
	}
	return heads
}

func (t *Tree) String() string {
	var buf = bytes.NewBuffer(nil)
	t.IterateSkip(t.RootId(), func(c *Change) (isContinue bool) {
		buf.WriteString(c.Id)
		if len(c.Next) > 1 {
			buf.WriteString("-<")
		} else if len(c.Next) > 0 {
			buf.WriteString("->")
		} else {
			buf.WriteString("-|")
		}
		return true
	})
	return buf.String()
}

func (t *Tree) Get(id string) *Change {
	return t.attached[id]
}

