package objecttree

import (
	"context"
	"errors"
	"fmt"

	"go.uber.org/zap"
	"golang.org/x/exp/slices"
	"golang.org/x/tools/container/intsets"

	"github.com/anyproto/any-sync/app/logger"
	"github.com/anyproto/any-sync/commonspace/object/tree/treechangeproto"
	"github.com/anyproto/any-sync/util/slice"
)

var (
	log      = logger.NewNamedSugared("common.commonspace.objecttree")
	ErrEmpty = errors.New("database is empty")
)

type treeBuilder struct {
	builder ChangeBuilder
	storage Storage
	ctx     context.Context

	// buffers
	idStack    []string
	loadBuffer []*Change
}

type treeBuilderOpts struct {
	full              bool
	useHeadsSnapshot  bool
	theirHeads        []string
	ourHeads          []string
	ourSnapshotPath   []string
	theirSnapshotPath []string
	newChanges        []*Change
}

func newTreeBuilder(storage Storage, builder ChangeBuilder) *treeBuilder {
	return &treeBuilder{
		storage: storage,
		builder: builder,
	}
}

func (tb *treeBuilder) BuildFull() (*Tree, error) {
	return tb.build(treeBuilderOpts{full: true})
}

func (tb *treeBuilder) buildWithAdded(opts treeBuilderOpts) (*Tree, []*Change, error) {
	cache := make(map[string]*Change)
	tb.ctx = context.Background()
	for _, ch := range opts.newChanges {
		cache[ch.Id] = ch
	}
	var (
		snapshot string
		order    string
	)
	if opts.useHeadsSnapshot {
		maxOrder, lowest, err := tb.lowestSnapshots(nil, opts.ourHeads, "")
		if err != nil {
			return nil, nil, err
		}
		if len(lowest) != 1 {
			snapshot, err = tb.commonSnapshot(lowest)
			if err != nil {
				return nil, nil, err
			}
		} else {
			snapshot = lowest[0]
		}
		order = maxOrder
	} else if !opts.full {
		if len(opts.theirSnapshotPath) == 0 {
			// this is actually not obvious why we should call this here
			// but the idea is if we have no snapshot path, then this can be only in cases
			// when we want to use a common snapshot, otherwise we would provide this path
			// because we always have a snapshot path
			if len(opts.ourSnapshotPath) == 0 {
				common, err := tb.storage.CommonSnapshot(tb.ctx)
				if err != nil {
					return nil, nil, err
				}
				snapshot = common
			} else {
				our := opts.ourSnapshotPath[0]
				_, lowest, err := tb.lowestSnapshots(cache, opts.theirHeads, our)
				if err != nil {
					return nil, nil, err
				}
				if len(lowest) != 1 {
					snapshot, err = tb.commonSnapshot(lowest)
					if err != nil {
						return nil, nil, err
					}
				} else {
					snapshot = lowest[0]
				}
			}
		} else {
			var err error
			snapshot, err = commonSnapshotForTwoPaths(opts.ourSnapshotPath, opts.theirSnapshotPath)
			if err != nil {
				return nil, nil, err
			}
		}
	} else {
		snapshot = tb.storage.Id()
	}
	snapshotCh, err := tb.storage.Get(tb.ctx, snapshot)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get common snapshot %s: %w", snapshot, err)
	}
	rawChange := &treechangeproto.RawTreeChangeWithId{}
	var (
		changes    = make([]*Change, 0, 10)
		newChanges = make([]*Change, 0, 10)
	)
	err = tb.storage.GetAfterOrder(tb.ctx, snapshotCh.OrderId, func(ctx context.Context, storageChange StorageChange) (shouldContinue bool, err error) {
		if order != "" && storageChange.OrderId > order {
			return false, nil
		}
		rawChange.Id = storageChange.Id
		rawChange.RawChange = storageChange.RawChange
		ch, err := tb.builder.Unmarshall(rawChange, false)
		if err != nil {
			return false, err
		}
		ch.OrderId = storageChange.OrderId
		ch.SnapshotCounter = storageChange.SnapshotCounter
		ch.AddSeq = storageChange.AddSeq
		changes = append(changes, ch)
		if _, contains := cache[ch.Id]; contains {
			delete(cache, ch.Id)
		}
		return true, nil
	})
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get changes after order: %w", err)
	}
	// getting the filtered new changes, we know that we don't have them in storage
	for _, change := range cache {
		newChanges = append(newChanges, change)
	}
	if len(changes) == 0 {
		return nil, nil, ErrEmpty
	}
	tr := &Tree{}
	changes = append(changes, newChanges...)
	added := tr.AddFast(changes...)
	if opts.useHeadsSnapshot {
		// this is important for history, because by default we get everything after the snapshot
		tr.LeaveOnlyBefore(opts.ourHeads)
	}
	if len(newChanges) > 0 {
		newChanges = newChanges[:0]
		for _, change := range added {
			// only those that are both added and are new we deem newChanges
			if _, contains := cache[change.Id]; contains {
				newChanges = append(newChanges, change)
			}
		}
		return tr, newChanges, nil
	}
	return tr, nil, nil
}

func (tb *treeBuilder) build(opts treeBuilderOpts) (tr *Tree, err error) {
	tr, _, err = tb.buildWithAdded(opts)
	return
}

func (tb *treeBuilder) lowestSnapshots(cache map[string]*Change, heads []string, ourSnapshot string) (maxOrder string, snapshots []string, err error) {
	var next, current []string
	if cache != nil {
		for _, ch := range heads {
			head, ok := cache[ch]
			if !ok {
				continue
			}
			if head.SnapshotId != "" {
				next = append(next, head.SnapshotId)
			} else if len(head.PreviousIds) == 0 && head.Id == tb.storage.Id() { // this is a root change
				next = append(next, head.Id)
			} else {
				return "", nil, fmt.Errorf("head with empty snapshot id: %s", head.Id)
			}
		}
	} else {
		for _, head := range heads {
			ch, err := tb.storage.Get(tb.ctx, head)
			if err != nil {
				return "", nil, err
			}
			if ch.OrderId > maxOrder {
				maxOrder = ch.OrderId
			}
			// TODO This is probably a bug, we might need to use next slice instead of snapshots
			if ch.SnapshotId != "" {
				snapshots = append(snapshots, ch.SnapshotId)
			} else if len(ch.PrevIds) == 0 && ch.Id == tb.storage.Id() { // this is a root change
				snapshots = append(snapshots, ch.Id)
			} else {
				return "", nil, fmt.Errorf("head with empty snapshot id: %s", ch.Id)
			}
		}
	}
	slices.Sort(next)
	next = slice.DiscardDuplicatesSorted(next)
	current = make([]string, 0, len(next))
	var visited []*Change
	for len(next) > 0 {
		current = current[:0]
		current = append(current, next...)
		next = next[:0]
		for _, id := range current {
			if ch, ok := cache[id]; ok && ch.SnapshotId != "" {
				if ch.visited {
					continue
				}
				ch.visited = true
				visited = append(visited, ch)
				next = append(next, ch.SnapshotId)
			} else {
				// this is the lowest snapshot from the ones provided
				snapshots = append(snapshots, id)
			}
		}
	}
	for _, ch := range visited {
		ch.visited = false
	}
	if ourSnapshot != "" {
		snapshots = append(snapshots, ourSnapshot)
	}
	slices.Sort(snapshots)
	snapshots = slice.DiscardDuplicatesSorted(snapshots)
	return maxOrder, snapshots, nil
}

// commonSnapshot returns the id of a snapshot where all other branches intersect
/*
For example, in this tree we starts from snapshots [sn 8, sn 6, sn 7] and get sn 2 as the common snapshot.
     ┌────┐
     │sn 1│
     └┬───┘
     ┌▽──────┐
     │sn 2   │
     └┬─────┬┘
     ┌▽───┐┌▽──────┐
     │sn 3││sn 4   │
     └┬───┘└┬─────┬┘
     ┌▽───┐┌▽───┐┌▽───┐
     │sn 5││sn 6││sn 7│
     └┬───┘└────┘└────┘
     ┌▽───┐
     │sn 8│
     └────┘
*/
func (tb *treeBuilder) commonSnapshot(snapshots []string) (snapshot string, err error) {
	var (
		current       []StorageChange
		lowestCounter = intsets.MaxInt
	)
	// TODO: we should actually check for all changes if they have valid snapshots
	// getting actual snapshots
	for _, id := range snapshots {
		ch, err := tb.storage.Get(tb.ctx, id)
		if err != nil {
			log.Error("failed to get snapshot", zap.String("id", id), zap.Error(err))
			continue
		}
		current = append(current, ch)
		if ch.SnapshotCounter < lowestCounter {
			lowestCounter = ch.SnapshotCounter
		}
	}
	// Equalizing depths for each snapshot branch
	// The result of this operation for example tree is [sn 5, sn 6, sn 7]
	for i, ch := range current {
		// Go down the tree to the older snapshots until all current snapshot branches don't have the same level
		for ch.SnapshotCounter > lowestCounter {
			ch, err = tb.storage.Get(tb.ctx, ch.SnapshotId)
			if err != nil {
				return "", fmt.Errorf("failed to get snapshot: %w", err)
			}
		}
		current[i] = ch
	}

	// Find the common snapshot by gradually going down the tree for each snapshot until we find a single intersection point
	// This point is the common snapshot.
	// Step-by-step example:
	// 1. We start from [sn 5, sn 6, sn 7]
	// 2. No duplicates, so proceed to going down the tree: [sn 3, sn 4, sn 4]
	// 3. Remove duplicates: [sn 3, sn 4]
	// 4. Go down the tree: [sn 2, sn 2]
	// 5. Remove duplicates: [sn 2]
	// 6. sn 2 is the only snapshot left, it's the common snapshot
	for {
		slices.SortFunc(current, func(a, b StorageChange) int {
			if a.SnapshotId < b.SnapshotId {
				return -1
			}
			if a.SnapshotId > b.SnapshotId {
				return 1
			}
			return 0
		})
		// Remove duplicated snapshots. Duplicated snapshots mean that multiple branches converged to a single branch
		current = slice.DiscardDuplicatesSortedFunc(current, func(a, b StorageChange) bool {
			return a.SnapshotId == b.SnapshotId
		})
		// if there is only one snapshot left - return it
		if len(current) == 1 {
			return current[0].Id, nil
		}
		// go down one level
		for i, ch := range current {
			ch, err = tb.storage.Get(tb.ctx, ch.SnapshotId)
			if err != nil {
				return "", fmt.Errorf("failed to get snapshot: %w", err)
			}
			current[i] = ch
		}
	}
}

commonspace/object/tree/objecttree/treem.text:
package objecttree

import (
	"context"
	"errors"
	"fmt"
	"sync/atomic"

	anystore "github.com/anyproto/any-store"

	"github.com/anyproto/any-sync/commonspace/headsync/headstorage"
	"github.com/anyproto/any-sync/commonspace/object/acl/list"
	"github.com/anyproto/any-sync/commonspace/object/tree/treechangeproto"
	"github.com/anyproto/any-sync/commonspace/object/tree/treestorage"
	"github.com/anyproto/any-sync/util/crypto"
	"github.com/anyproto/any-sync/util/slice"
)

type treeStorage interface {
	Id() string
	Root() (*treechangeproto.RawTreeChangeWithId, error)
	Heads() ([]string, error)
	SetHeads(heads []string) error
	AddRawChange(change *treechangeproto.RawTreeChangeWithId) error
	AddRawChangesSetHeads(changes []*treechangeproto.RawTreeChangeWithId, heads []string) error
	GetAllChangeIds() ([]string, error)

	GetRawChange(ctx context.Context, id string) (*treechangeproto.RawTreeChangeWithId, error)
	GetAppendRawChange(ctx context.Context, buf []byte, id string) (*treechangeproto.RawTreeChangeWithId, error)
	HasChange(ctx context.Context, id string) (bool, error)
	Delete() error
}

type changesIterator interface {
	GetAllChanges() ([]*treechangeproto.RawTreeChangeWithId, error)
	IterateChanges(proc func(id string, rawChange []byte) error) error
}

type TreeMigrator struct {
	idStack    []string
	cache      map[string]*Change
	storage    treeStorage
	builder    ChangeBuilder
	allChanges []*treechangeproto.RawTreeChangeWithId

	keyStorage crypto.KeyStorage
	aclList    list.AclList
}

func NewTreeMigrator(keyStorage crypto.KeyStorage, aclList list.AclList) *TreeMigrator {
	return &TreeMigrator{
		keyStorage: keyStorage,
		aclList:    aclList,
	}
}

func (tm *TreeMigrator) MigrateTreeStorage(ctx context.Context, storage treeStorage, headStorage headstorage.HeadStorage, store anystore.DB) error {
	rootChange, err := storage.Root()
	if err != nil {
		return err
	}
	tm.allChanges = []*treechangeproto.RawTreeChangeWithId{rootChange}
	tm.storage = storage
	tm.cache = make(map[string]*Change)
	tm.builder = NewChangeBuilder(tm.keyStorage, rootChange)
	tm.builder = &nonVerifiableChangeBuilder{tm.builder}
	heads, err := storage.Heads()
	if err != nil {
		return fmt.Errorf("migration: failed to get heads: %w", err)
	}
	if iterStore, ok := storage.(changesIterator); ok {
		tm.allChanges, err = iterStore.GetAllChanges()
		if err != nil {
			return fmt.Errorf("migration: failed to get all changes: %w", err)
		}
	} else {
		tm.dfs(ctx, heads, rootChange.Id)
	}
	newStorage, err := CreateStorage(ctx, rootChange, headStorage, store)
	if err != nil && !errors.Is(err, treestorage.ErrTreeExists) {
		return fmt.Errorf("migration: failed to create new storage: %w", err)
	}
	if errors.Is(err, treestorage.ErrTreeExists) {
		newStorage, err = NewStorage(ctx, rootChange.Id, headStorage, store)
		if err != nil {
			return fmt.Errorf("migration: failed to start old storage: %w", err)
		}
	}
	// Set up AddSeq counter so storage.AddAll can assign sequence numbers
	if setter, ok := newStorage.(interface{ SetAddSeq(seq *atomic.Uint64) }); ok {
		setter.SetAddSeq(&atomic.Uint64{})
	}
	objTree, err := BuildMigratableObjectTree(newStorage, tm.aclList)
	if err != nil {
		return fmt.Errorf("migration: failed to build object tree: %w", err)
	}
	addPayload := RawChangesPayload{
		NewHeads:     heads,
		RawChanges:   tm.allChanges,
		SnapshotPath: []string{rootChange.Id},
	}
	objTree.Lock()
	res, err := objTree.AddRawChanges(ctx, addPayload)
	objTree.Unlock()
	if err != nil {
		return fmt.Errorf("migration: failed to add raw changes: %w", err)
	}
	if !slice.UnsortedEquals(res.Heads, heads) {
		log.Errorf("migration: heads mismatch: %v, %v != %v", rootChange.Id, res.Heads, heads)
	}
	return nil
}

func (tm *TreeMigrator) dfs(ctx context.Context, heads []string, breakpoint string) (loadFailed bool) {
	tm.idStack = tm.idStack[:0]
	uniqMap := map[string]struct{}{breakpoint: {}}
	tm.idStack = append(tm.idStack, heads...)

	for len(tm.idStack) > 0 {
		id := tm.idStack[len(tm.idStack)-1]
		tm.idStack = tm.idStack[:len(tm.idStack)-1]
		if _, exists := uniqMap[id]; exists {
			continue
		}

		ch, err := tm.loadChange(ctx, id)
		if err != nil {
			loadFailed = true
			continue
		}

		uniqMap[id] = struct{}{}
		for _, prev := range ch.PreviousIds {
			if _, exists := uniqMap[prev]; exists {
				continue
			}
			tm.idStack = append(tm.idStack, prev)
		}
	}
	return
}

func (tm *TreeMigrator) loadChange(ctx context.Context, id string) (ch *Change, err error) {
	if ch, ok := tm.cache[id]; ok {
		return ch, nil
	}

	change, err := tm.storage.GetRawChange(ctx, id)
	if err != nil {
		return nil, err
	}
	tm.allChanges = append(tm.allChanges, change)
	ch, err = tm.builder.UnmarshallReduced(change)
	if err != nil {
		return nil, err
	}
	tm.cache[id] = ch
	return ch, nil
}

core/acl/aclservice.go.text:
package acl

/*
AI generated

Name: Space Access Control and Sharing
Scope: global

## Responsibility
- Space invite management (generate, view, change, revoke invites for member/guest/anyone types)
- ACL membership operations (join, leave, accept, decline, remove participants)
- Permission management (change participant permissions, approve leave requests)
- Guest user account management

## Background Tasks
- aclUpdater: monitors participants with "Removing" status via cross-space subscription,
  schedules automatic ApproveLeave for owners; monitors space views for spaces where user
  should self-remove, schedules Leave retries. Uses retryscheduler for exponential backoff.

## Documentation
The aclUpdater coordinates two subscription-based flows:
1. participantSub: subscribes to participants with status=Removing across all owned spaces,
   triggers ApproveLeave for each (owner auto-approves leave requests)
2. spaceSubscription: subscribes to space views where user is not owner but space is deleted,
   triggers self-Leave requests with retry logic
Both flows use a shared retryscheduler that handles failures with exponential backoff.
*/

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"sync"
	"time"

	"github.com/anyproto/any-sync/app"
	"github.com/anyproto/any-sync/commonspace/acl/aclclient"
	"github.com/anyproto/any-sync/commonspace/object/acl/aclrecordproto"
	"github.com/anyproto/any-sync/commonspace/object/acl/list"
	"github.com/anyproto/any-sync/commonspace/object/acl/recordverifier"
	"github.com/anyproto/any-sync/consensus/consensusproto/consensuserr"
	"github.com/anyproto/any-sync/coordinator/coordinatorclient"
	"github.com/anyproto/any-sync/coordinator/coordinatorproto"
	"github.com/anyproto/any-sync/identityrepo/identityrepoproto"
	"github.com/anyproto/any-sync/nodeconf"
	"github.com/anyproto/any-sync/util/crypto"
	"github.com/ipfs/go-cid"
	"go.uber.org/zap"

	"github.com/anyproto/anytype-heart/core/anytype/account"
	"github.com/anyproto/anytype-heart/core/domain"
	"github.com/anyproto/anytype-heart/core/invitecleanup"
	"github.com/anyproto/anytype-heart/core/inviteservice"
	"github.com/anyproto/anytype-heart/core/subscription"
	"github.com/anyproto/anytype-heart/core/subscription/crossspacesub"
	"github.com/anyproto/anytype-heart/core/wallet"
	"github.com/anyproto/anytype-heart/pkg/lib/bundle"
	"github.com/anyproto/anytype-heart/pkg/lib/logging"
	"github.com/anyproto/anytype-heart/pkg/lib/pb/model"
	"github.com/anyproto/anytype-heart/space"
	"github.com/anyproto/anytype-heart/space/spaceinfo"
	"github.com/anyproto/anytype-heart/space/techspace"
)

const CName = "common.acl.aclservice"

var log = logging.LoggerNotSugared(CName)

var sleepTime = time.Millisecond * 500

type NodeConfGetter interface {
	GetNodeConf() (conf nodeconf.Configuration)
}

type AccountPermissions struct {
	Account     crypto.PubKey
	Permissions model.ParticipantPermissions
}

type AclService interface {
	app.Component
	GenerateInvite(ctx context.Context, spaceId string, inviteType model.InviteType, permissions model.ParticipantPermissions, shareWithinSpace bool) (domain.InviteInfo, error)
	ChangeInvite(ctx context.Context, spaceId string, permissions model.ParticipantPermissions) error
	RevokeInvite(ctx context.Context, spaceId string) error
	GetCurrentInvite(ctx context.Context, spaceId string) (domain.InviteInfo, error)
	GetGuestUserInvite(ctx context.Context, spaceId string) (domain.InviteInfo, error)
	ViewInvite(ctx context.Context, inviteCid cid.Cid, inviteFileKey crypto.SymKey) (domain.InviteView, error)
	Join(ctx context.Context, spaceId, networkId string, inviteCid cid.Cid, inviteFileKey crypto.SymKey) error
	ApproveLeave(ctx context.Context, spaceId string, identities []crypto.PubKey) error
	MakeShareable(ctx context.Context, spaceId string) error
	StopSharing(ctx context.Context, spaceId string) error
	CancelJoin(ctx context.Context, spaceId string) (err error)
	Accept(ctx context.Context, spaceId string, identity crypto.PubKey, permissions model.ParticipantPermissions) error
	Decline(ctx context.Context, spaceId string, identity crypto.PubKey) (err error)
	Leave(ctx context.Context, spaceId string) (err error)
	Remove(ctx context.Context, spaceId string, identities []crypto.PubKey) (err error)
	ChangePermissions(ctx context.Context, spaceId string, perms []AccountPermissions) (err error)
	AddAccounts(ctx context.Context, spaceId string, additions []list.AccountAdd) error
	AddGuestAccount(ctx context.Context, spaceId string) (privKey crypto.PrivKey, err error)
	OwnershipChange(ctx context.Context, spaceId string, newOwner crypto.PubKey, oldOwnerPerm model.ParticipantPermissions) (err error)
}

func New() AclService {
	return &aclService{}
}

type identityRepoClient interface {
	app.Component
	IdentityRepoPut(ctx context.Context, identity string, data []*identityrepoproto.Data) (err error)
	IdentityRepoGet(ctx context.Context, identities []string, kinds []string) (res []*identityrepoproto.DataWithIdentity, err error)
}

type aclService struct {
	nodeConfigGetter NodeConfGetter
	nodeConf         nodeconf.Service
	joiningClient    aclclient.AclJoiningClient
	spaceService     space.Service
	inviteService    inviteservice.InviteService
	inviteCleanup    invitecleanup.Service
	accountService   account.Service
	coordClient      coordinatorclient.CoordinatorClient
	identityRepo     identityRepoClient
	recordVerifier   recordverifier.AcceptorVerifier
	updater          *aclUpdater
	getter           *aclGetter

	// aclClientLock serializes all ACL modification operations.
	// This prevents race conditions where concurrent operations (e.g. GenerateInvite
	// and AddAccounts) read the same ACL head, build records with the same prevId,
	// and only one succeeds on the node ("incorrect prev id of a record" error).
	aclClientLock sync.Mutex

	ctx       context.Context
	ctxCancel context.CancelFunc
}

func (a *aclService) Init(ap *app.App) (err error) {
	a.nodeConfigGetter = app.MustComponent[NodeConfGetter](ap)
	a.nodeConf = app.MustComponent[nodeconf.Service](ap)
	a.joiningClient = app.MustComponent[aclclient.AclJoiningClient](ap)
	a.spaceService = app.MustComponent[space.Service](ap)
	a.accountService = app.MustComponent[account.Service](ap)
	a.inviteService = app.MustComponent[inviteservice.InviteService](ap)
	a.inviteCleanup = app.MustComponent[invitecleanup.Service](ap)
	a.coordClient = app.MustComponent[coordinatorclient.CoordinatorClient](ap)
	a.identityRepo = app.MustComponent[identityRepoClient](ap)
	subService := app.MustComponent[subscription.Service](ap)
	crossSub := app.MustComponent[crossspacesub.Service](ap)
	wlt := app.MustComponent[wallet.Wallet](ap)
	a.getter = newAclGetter(a.joiningClient, wlt.Account(), a.nodeConf)
	a.updater, err = newAclUpdater("acl-updater",
		wlt.Account().SignKey.GetPublic().Account(),
		crossSub,
		subService,
		a.spaceService.TechSpaceId(),
		a,
		1*time.Second,
		30*time.Second,
		10*time.Second)
	if err != nil {
		return err
	}

	a.ctx, a.ctxCancel = context.WithCancel(context.Background())
	return nil
}

// buildRecordVerifier returns the test-injected verifier when present, otherwise
// builds one from the current networkId. We decode lazily because in LocalOnly
// mode networkId is empty; in that mode there are no acceptor-signed records
// to check, so we fall back to the no-op verifier.
func (a *aclService) buildRecordVerifier() (recordverifier.AcceptorVerifier, error) {
	if a.recordVerifier != nil {
		return a.recordVerifier, nil
	}
	networkId := a.nodeConf.Configuration().NetworkId
	if networkId == "" {
		return recordverifier.NewValidateFull(), nil
	}
	netKey, err := crypto.DecodeNetworkId(networkId)
	if err != nil {
		return nil, fmt.Errorf("invalid networkId: %w", err)
	}
	return recordverifier.New(netKey), nil
}

func (a *aclService) Run(_ context.Context) (err error) {
	if a.updater != nil {
		go func() {
			err = a.updater.Run(a.ctx)
			if err != nil {
				log.With(zap.Error(err)).Error("acl updater run error")
			}
		}()
	}
	return nil
}

func (a *aclService) Close(ctx context.Context) (err error) {
	a.ctxCancel()
	if a.updater != nil {
		// Close always waiting for Run to finish under the hood
		return a.updater.Close()
	}
	return nil
}

func (a *aclService) Name() (name string) {
	return CName
}

func (a *aclService) MakeShareable(ctx context.Context, spaceId string) error {
	err := a.coordClient.SpaceMakeShareable(ctx, spaceId)
	if err != nil {
		return convertedOrInternalError("make shareable", err)
	}
	info := spaceinfo.NewSpaceLocalInfo(spaceId)
	info.SetShareableStatus(spaceinfo.ShareableStatusShareable)
	err = a.spaceService.TechSpace().SetLocalInfo(ctx, info)
	if err != nil {
		return convertedOrInternalError("set local info", err)
	}
	return nil
}

func (a *aclService) pushGuest(ctx context.Context, privKey crypto.PrivKey) (metadata []byte, err error) {
	metadataModel, _, err := domain.DeriveAccountMetadata(privKey)
	if err != nil {
		return nil, fmt.Errorf("derive account metadata: %w", err)
	}
	metadata, err = metadataModel.Marshal()
	if err != nil {
		return nil, fmt.Errorf("marshal metadata: %w", err)
	}
	return
}

func (a *aclService) AddGuestAccount(ctx context.Context, spaceId string) (privKey crypto.PrivKey, err error) {
	pk, pubKey, err := crypto.GenerateRandomEd25519KeyPair()
	if err != nil {
		return nil, err
	}
	metadata, err := a.pushGuest(ctx, pk)
	if err != nil {
		return nil, err
	}
	return pk, a.AddAccounts(ctx, spaceId, []list.AccountAdd{{
		Identity:    pubKey,
		Metadata:    metadata,
		Permissions: list.AclPermissionsGuest,
	}})
}

func (a *aclService) AddAccounts(ctx context.Context, spaceId string, additions []list.AccountAdd) error {
	sp, err := a.spaceService.Get(ctx, spaceId)
	if err != nil {
		return convertedOrSpaceErr(err)
	}
	a.aclClientLock.Lock()
	defer a.aclClientLock.Unlock()
	err = sp.CommonSpace().AclClient().AddAccounts(ctx, list.AccountsAddPayload{Additions: additions})
	if err != nil {
		return convertedOrAclRequestError(err)
	}
	return nil
}

func (a *aclService) Remove(ctx context.Context, spaceId string, identities []crypto.PubKey) error {
	removeSpace, err := a.spaceService.Get(ctx, spaceId)
	if err != nil {
		return convertedOrSpaceErr(err)
	}
	newPrivKey, _, err := crypto.GenerateRandomEd25519KeyPair()
	if err != nil {
		return convertedOrInternalError("generate random key pair", err)
	}
	cl := removeSpace.CommonSpace().AclClient()
	a.aclClientLock.Lock()
	defer a.aclClientLock.Unlock()
	err = cl.RemoveAccounts(ctx, list.AccountRemovePayload{
		Identities: identities,
		Change: list.ReadKeyChangePayload{
			MetadataKey: newPrivKey,
			ReadKey:     crypto.NewAES(),
		},
	})
	if err != nil {
		return convertedOrAclRequestError(err)
	}
	return nil
}

// RotateReadKey generates a new space read key when retiring a revoked AnyoneCanJoin invite. It is the
// invitecleanup.readKeyRotator implementation.
//
// It only sends the rotation while the acl head is still expectedHead — the head the cleanup decided
// the rotation on. If the acl has moved (another device rotated, or any acl change landed), it returns
// invitecleanup.ErrAclHeadChanged and does nothing, so the rotation is never applied to state that
// changed under the decision. The record itself carries prevId = the current head, so the coordinator
// rejects a rotation built on a head it has since advanced past; that rejection maps to the same
// sentinel.
func (a *aclService) RotateReadKey(ctx context.Context, spaceId string, expectedHead string) error {
	sp, err := a.spaceService.Get(ctx, spaceId)
	if err != nil {
		return convertedOrSpaceErr(err)
	}
	change, err := newReadKeyChange()
	if err != nil {
		return convertedOrInternalError("generate read key change", err)
	}
	acl := sp.CommonSpace().Acl()
	cl := sp.CommonSpace().AclClient()

	a.aclClientLock.Lock()
	defer a.aclClientLock.Unlock()

	acl.RLock()
	sameHead := acl.Head().Id == expectedHead
	acl.RUnlock()
	if !sameHead {
		return invitecleanup.ErrAclHeadChanged
	}

	// a bare read-key change, not RevokeAllInvitesAndRotate: the backlog invite is already revoked, and
	// any invite that is still live is legitimate and must survive — a pure rotation re-keys live
	// invites and members while excluding the already-revoked ones.
	acl.Lock()
	rec, err := acl.RecordBuilder().BuildReadKeyChange(change)
	acl.Unlock()
	if err != nil {
		return convertedOrInternalError("build read key change", err)
	}

	if err = cl.AddRecord(ctx, rec); err != nil {
		// the acl head moved between the local head check and the node accepting the record: a local
		// prev-id mismatch (ErrIncorrectRecordSequence) or the node rejecting a record built on a head
		// it has advanced past (consensus ErrConflict). Either way the rotation another device most
		// likely already made stands, and this one is abandoned for the next launch.
		if errors.Is(err, list.ErrIncorrectRecordSequence) ||
			errors.Is(err, consensuserr.ErrConflict) ||
			strings.Contains(err.Error(), "incorrect prev id") {
			return invitecleanup.ErrAclHeadChanged
		}
		return convertedOrAclRequestError(err)
	}
	return nil
}

func (a *aclService) CancelJoin(ctx context.Context, spaceId string) (err error) {
	err = a.joiningClient.CancelJoin(ctx, spaceId)
	if err != nil {
		return convertedOrAclRequestError(err)
	}
	err = a.spaceService.Delete(ctx, spaceId)
	if err != nil {
		return convertedOrInternalError("delete space", err)
	}
	return nil
}

func (a *aclService) Decline(ctx context.Context, spaceId string, identity crypto.PubKey) (err error) {
	sp, err := a.spaceService.Get(ctx, spaceId)
	if err != nil {
		return convertedOrSpaceErr(err)
	}
	cl := sp.CommonSpace().AclClient()
	a.aclClientLock.Lock()
	defer a.aclClientLock.Unlock()
	err = cl.DeclineRequest(ctx, identity)
	if err != nil {
		return convertedOrAclRequestError(err)
	}
	return nil
}

func (a *aclService) RevokeInvite(ctx context.Context, spaceId string) error {
	sp, err := a.spaceService.Get(ctx, spaceId)
	if err != nil {
		return convertedOrSpaceErr(err)
	}
	commonSpace := sp.CommonSpace()
	cl := commonSpace.AclClient()
	acl := commonSpace.Acl()
	a.aclClientLock.Lock()
	err = revokeAllInvites(ctx, cl, acl)
	a.aclClientLock.Unlock()
	if err != nil {
		return convertedOrAclRequestError(err)
	}
	revoked, err := a.inviteService.RemoveExisting(ctx, spaceId)
	if err != nil {
		return convertedOrInternalError("remove existing invite", err)
	}
	a.onInviteRevoked(ctx, spaceId, revoked)
	return nil
}

// revokeAllInvites revokes every invite the space has, rotating the read key when any of them is one
// anyone can join with. That kind of invite embeds the read key, so revoking it is not enough — the
// key it handed out has to be rotated away or it keeps decrypting content created after the revocation.
func revokeAllInvites(ctx context.Context, cl aclclient.AclSpaceClient, acl list.AclList) error {
	if !hasAnyoneCanJoinInvite(acl) {
		return cl.RevokeAllInvites(ctx)
	}
	change, err := newReadKeyChange()
	if err != nil {
		return err
	}
	return cl.RevokeAllInvitesAndRotate(ctx, change)
}

// hasAnyoneCanJoinInvite reports whether the space currently offers an invite anyone can join with.
func hasAnyoneCanJoinInvite(acl list.AclList) bool {
	acl.RLock()
	defer acl.RUnlock()
	return len(acl.AclState().Invites(aclrecordproto.AclInviteType_AnyoneCanJoin)) > 0
}

func newReadKeyChange() (list.ReadKeyChangePayload, error) {
	metadataKey, _, err := crypto.GenerateRandomEd25519KeyPair()
	if err != nil {
		return list.ReadKeyChangePayload{}, err
	}
	return list.ReadKeyChangePayload{MetadataKey: metadataKey, ReadKey: crypto.NewAES()}, nil
}

// onInviteRevoked hands an invite the acl has just revoked to the cleanup service, which deletes its
// file. It runs only once the revocation has gone through, it must not run while aclClientLock is
// held, and it never fails the caller: the invite is revoked either way, and the background pass
// retries whatever the deletion does not finish — the revocation record has already voided the
// space's clean certificate, so the pass will come back for it.
func (a *aclService) onInviteRevoked(ctx context.Context, spaceId string, revoked domain.InviteInfo) {
	if revoked.InviteFileCid == "" {
		return
	}
	if err := a.inviteCleanup.InviteRevoked(ctx, spaceId, revoked); err != nil {
		log.Warn("delete revoked invite file", zap.String("spaceId", spaceId), zap.Error(err))
	}
}

func (a *aclService) ChangePermissions(ctx context.Context, spaceId string, perms []AccountPermissions) error {
	if len(perms) == 0 {
		return fmt.Errorf("%w: empty permissions", ErrIncorrectPermissions)
	}
	sp, err := a.spaceService.Get(ctx, spaceId)
	if err != nil {
		return convertedOrSpaceErr(err)
	}
	var listPerms []list.PermissionChangePayload
	acl := sp.CommonSpace().Acl()
	acl.RLock()
	for _, perm := range perms {
		var aclPerms list.AclPermissions
		switch perm.Permissions {
		case model.ParticipantPermissions_Reader:
			aclPerms = list.AclPermissionsReader
		case model.ParticipantPermissions_Writer:
			aclPerms = list.AclPermissionsWriter
		case model.ParticipantPermissions_Admin:
			aclPerms = list.AclPermissionsAdmin
		default:
			acl.RUnlock()
			return ErrIncorrectPermissions
		}
		curPerms := acl.AclState().Permissions(perm.Account)
		if curPerms.NoPermissions() {
			acl.RUnlock()
			return ErrNoSuchAccount
		}
		if curPerms == aclPerms {
			continue
		}
		listPerms = append(listPerms, list.PermissionChangePayload{
			Identity:    perm.Account,
			Permissions: aclPerms,
		})
	}
	acl.RUnlock()
	cl := sp.CommonSpace().AclClient()
	a.aclClientLock.Lock()
	defer a.aclClientLock.Unlock()
	err = cl.ChangePermissions(ctx, list.PermissionChangesPayload{
		Changes: listPerms,
	})
	if err != nil {
		return convertedOrAclRequestError(err)
	}
	return nil
}

func (a *aclService) ApproveLeave(ctx context.Context, spaceId string, identities []crypto.PubKey) error {
	sp, err := a.spaceService.Get(ctx, spaceId)
	if err != nil {
		return convertedOrSpaceErr(err)
	}
	acl := sp.CommonSpace().Acl()
	acl.RLock()
	st := acl.AclState()
	identitiesMap := map[string]struct{}{}
	for _, identity := range identities {
		identitiesMap[identity.Account()] = struct{}{}
	}
	for _, rec := range st.RemoveRecords() {
		for _, identity := range identities {
			if rec.RequestIdentity.Equals(identity) {
				delete(identitiesMap, identity.Account())
			}
		}
	}
	if len(identitiesMap) != 0 {
		acl.RUnlock()
		identities := make([]string, 0, len(identitiesMap))
		for identity := range identitiesMap {
			identities = append(identities, identity)
		}
		return fmt.Errorf("%w with identities: %s", ErrRequestNotExists, strings.Join(identities, ", "))
	}
	acl.RUnlock()
	return a.Remove(ctx, spaceId, identities)
}

func (a *aclService) Leave(ctx context.Context, spaceId string) (err error) {
	// all check are happening in acl updater
	aclList, err := a.getter.GetOrRefreshAcl(ctx, spaceId)
	if err != nil {
		return convertedOrAclRequestError(err)
	}
	myIdentity := aclList.AclState().Identity()
	defer func() {
		for _, state := range aclList.AclState().CurrentAccounts() {
			if state.PubKey.Equals(myIdentity) {
				err = a.spaceService.TechSpace().DoSpaceView(ctx, spaceId, func(spaceView techspace.SpaceView) error {
					return spaceView.SetMyParticipantStatus(domain.ConvertAclStatus(state.Status))
				})
			}
		}
	}()
	err = a.joiningClient.RequestSelfRemove(ctx, spaceId, aclList)
	if err != nil {
		return convertedOrAclRequestError(err)
	}
	// We've left the space, so drop the network-fetched ACL copy the getter cached for
	// this operation; otherwise it lingers in currentAcls for the rest of the session.
	if removeErr := a.getter.RemoveAcl(ctx, spaceId); removeErr != nil {
		log.Warn("remove acl from getter cache after leave", zap.Error(removeErr), zap.String("spaceId", spaceId))
	}
	return nil
}

func (a *aclService) StopSharing(ctx context.Context, spaceId string) error {
	removeSpace, err := a.spaceService.Get(ctx, spaceId)
	if err != nil {
		return convertedOrSpaceErr(err)
	}
	var (
		commonSpace = removeSpace.CommonSpace()
		acl         = commonSpace.Acl()
		techSpace   = a.spaceService.TechSpace()
		localInfo   spaceinfo.SpaceLocalInfo
	)
	err = techSpace.DoSpaceView(ctx, spaceId, func(spaceView techspace.SpaceView) error {
		localInfo = spaceView.GetLocalInfo()
		return nil
	})
	if err != nil {
		return convertedOrInternalError("get local info", err)
	}
	newPrivKey, _, err := crypto.GenerateRandomEd25519KeyPair()
	if err != nil {
		return convertedOrInternalError("generate random key pair", err)
	}
	cl := commonSpace.AclClient()
	a.aclClientLock.Lock()
	err = cl.StopSharing(ctx, list.ReadKeyChangePayload{
		MetadataKey: newPrivKey,
		ReadKey:     crypto.NewAES(),
	})
	a.aclClientLock.Unlock()
	if err != nil {
		return convertedOrAclRequestError(err)
	}
	acl.RLock()
	head := acl.Head().Id
	acl.RUnlock()
	revoked, err := a.inviteService.RemoveExisting(ctx, spaceId)
	if err != nil {
		return convertedOrInternalError("remove existing invite", err)
	}
	a.onInviteRevoked(ctx, spaceId, revoked)
	if localInfo.GetShareableStatus() != spaceinfo.ShareableStatusShareable {
		return nil
	}
	for {
		err = a.coordClient.SpaceMakeUnshareable(ctx, spaceId, head)
		if errors.Is(err, coordinatorproto.ErrAclHeadIsMissing) {
			time.Sleep(sleepTime)
			continue
		}
		break
	}
	if err != nil {
		return convertedOrAclRequestError(err)
	}
	info := spaceinfo.NewSpaceLocalInfo(spaceId)
	info.SetShareableStatus(spaceinfo.ShareableStatusNotShareable)
	err = techSpace.SetLocalInfo(ctx, info)
	if err != nil {
		return convertedOrInternalError("set local info", err)
	}
	return nil
}

func (a *aclService) Join(ctx context.Context, spaceId, networkId string, inviteCid cid.Cid, inviteFileKey crypto.SymKey) error {
	if a.nodeConfigGetter.GetNodeConf().NetworkId != networkId {
		return fmt.Errorf("%w. Local network: '%s', network of space to join: '%s'", ErrDifferentNetwork, a.nodeConfigGetter.GetNodeConf().NetworkId, networkId)
	}
	invitePayload, err := a.inviteService.GetPayload(ctx, inviteCid, inviteFileKey)
	if err != nil {
		return convertedOrInternalError("get invite payload", err)
	}
	onJoinError := func(err error) error {
		if errors.Is(err, coordinatorproto.ErrSpaceIsDeleted) {
			return space.ErrSpaceDeleted
		}
		if errors.Is(err, list.ErrInsufficientPermissions) {
			err = a.joiningClient.CancelRemoveSelf(ctx, spaceId)
			if err != nil {
				return convertedOrAclRequestError(err)
			}
			err = a.spaceService.CancelLeave(ctx, spaceId)
			if err != nil {
				return convertedOrInternalError("cancel leave", err)
			}
		}
		return convertedOrAclRequestError(err)
	}
	switch invitePayload.InviteType {
	case model.InviteType_Guest:
		guestKey, err := crypto.UnmarshalEd25519PrivateKeyProto(invitePayload.GuestKey)
		if err != nil {
			return convertedOrInternalError("unmarshal invite key", err)
		}
		return a.joinAsGuest(ctx, invitePayload.SpaceId, guestKey)
	case model.InviteType_Member:
		inviteKey, err := crypto.UnmarshalEd25519PrivateKeyProto(invitePayload.AclKey)
		if err != nil {
			return convertedOrInternalError("unmarshal invite key", err)
		}
		aclHeadId, err := a.joiningClient.RequestJoin(ctx, spaceId, list.RequestJoinPayload{
			InviteKey: inviteKey,
			Metadata:  a.spaceService.AccountMetadataPayload(),
		})
		// nolint: nestif
		if err != nil {
			return onJoinError(err)
		}
		err = a.spaceService.Join(ctx, spaceId, aclHeadId)
		if err != nil {
			return convertedOrInternalError("join space", err)
		}
		err = a.spaceService.TechSpace().SpaceViewSetData(ctx, spaceId,
			domain.NewDetails().
				SetString(bundle.RelationKeyName, invitePayload.SpaceName).
				SetString(bundle.RelationKeyIconImage, invitePayload.SpaceIconCid).
				SetInt64(bundle.RelationKeyIconOption, int64(invitePayload.SpaceIconOption)).
				SetInt64(bundle.RelationKeySpaceUxType, int64(invitePayload.SpaceUxType)). // TODO: GO-7102 remove
				SetInt64(bundle.RelationKeySpaceType, int64(invitePayload.SpaceType)))
		if err != nil {
			return convertedOrInternalError("set space data", err)
		}
	case model.InviteType_WithoutApprove:
		inviteKey, err := crypto.UnmarshalEd25519PrivateKeyProto(invitePayload.AclKey)
		if err != nil {
			return convertedOrInternalError("unmarshal invite key", err)
		}
		aclHeadId, err := a.joiningClient.InviteJoin(ctx, spaceId, list.InviteJoinPayload{
			InviteKey: inviteKey,
			Metadata:  a.spaceService.AccountMetadataPayload(),
		})
		if errors.Is(err, coordinatorproto.ErrSpaceLimitReached) {
			aclHeadId, err = a.joiningClient.InviteJoin(ctx, spaceId, list.InviteJoinPayload{
				InviteKey:   inviteKey,
				Metadata:    a.spaceService.AccountMetadataPayload(),
				Permissions: list.AclPermissionsReader,
			})
		}
		if err != nil {
			return onJoinError(err)
		}
		err = a.spaceService.InviteJoin(ctx, spaceId, aclHeadId)
		if err != nil {
			return convertedOrInternalError("join space", err)
		}
		err = a.spaceService.TechSpace().SpaceViewSetData(ctx, spaceId,
			domain.NewDetails().
				SetString(bundle.RelationKeyName, invitePayload.SpaceName).
				SetString(bundle.RelationKeyIconImage, invitePayload.SpaceIconCid).
				SetInt64(bundle.RelationKeyIconOption, int64(invitePayload.SpaceIconOption)).
				SetInt64(bundle.RelationKeySpaceUxType, int64(invitePayload.SpaceUxType)). // TODO: GO-7102 remove
				SetInt64(bundle.RelationKeySpaceType, int64(invitePayload.SpaceType)))
		if err != nil {
			return convertedOrInternalError("set space data", err)
		}
	}
	return nil
}

func (a *aclService) ViewInvite(ctx context.Context, inviteCid cid.Cid, inviteFileKey crypto.SymKey) (domain.InviteView, error) {
	res, err := a.inviteService.View(ctx, inviteCid, inviteFileKey)
	if err != nil {
		return domain.InviteView{}, convertedOrInternalError("view invite", err)
	}
	if res.IsGuestUserInvite() {
		return domain.InviteView{
			SpaceId:         res.SpaceId,
			GuestKey:        res.GuestKey,
			SpaceName:       res.SpaceName,
			SpaceIconCid:    res.SpaceIconCid,
			SpaceIconOption: res.SpaceIconOption,
			SpaceUxType:     res.SpaceUxType,
			SpaceType:       res.SpaceType,
			CreatorName:     res.CreatorName,
			CreatorIconCid:  res.CreatorIconCid,
		}, nil
	}
	inviteKey, err := crypto.UnmarshalEd25519PrivateKeyProto(res.AclKey)
	if err != nil {
		return domain.InviteView{}, convertedOrInternalError("unmarshal invite key", err)
	}
	recs, err := a.joiningClient.AclGetRecords(ctx, res.SpaceId, "")
	if err != nil {
		return domain.InviteView{}, convertedOrAclRequestError(err)
	}
	if len(recs) == 0 {
		return domain.InviteView{}, fmt.Errorf("no acl records found for space: %s, %w", res.SpaceId, ErrAclRequestFailed)
	}
	store, err := list.NewInMemoryStorage(recs[0].Id, recs)
	if err != nil {
		return domain.InviteView{}, convertedOrAclRequestError(err)
	}
	verifier, err := a.buildRecordVerifier()
	if err != nil {
		return domain.InviteView{}, convertedOrInternalError("build record verifier", err)
	}
	lst, err := list.BuildAclListWithIdentity(a.accountService.Keys(), store, verifier)
	if err != nil {
		return domain.InviteView{}, convertedOrAclRequestError(err)
	}
	for _, inv := range lst.AclState().Invites() {
		if inviteKey.GetPublic().Equals(inv.Key) {
			return res, nil
		}
	}
	return domain.InviteView{}, inviteservice.ErrInviteNotExists
}

func (a *aclService) Accept(ctx context.Context, spaceId string, identity crypto.PubKey, permissions model.ParticipantPermissions) error {
	validPerms := permissions == model.ParticipantPermissions_Reader ||
		permissions == model.ParticipantPermissions_Writer ||
		permissions == model.ParticipantPermissions_Admin
	if !validPerms {
		return ErrIncorrectPermissions
	}
	acceptSpace, err := a.spaceService.Get(ctx, spaceId)
	if err != nil {
		return convertedOrSpaceErr(err)
	}
	acl := acceptSpace.CommonSpace().Acl()
	acl.RLock()
	recs, err := acl.AclState().JoinRecords(false)
	if err != nil {
		acl.RUnlock()
		return convertedOrInternalError("join records get error", err)
	}
	var recId string
	for _, rec := range recs {
		if rec.RequestIdentity.Equals(identity) {
			recId = rec.RecordId
			break
		}
	}
	acl.RUnlock()
	if recId == "" {
		return fmt.Errorf("%w with identity: %s", ErrRequestNotExists, identity.Account())
	}
	var aclPerms list.AclPermissions
	switch permissions {
	case model.ParticipantPermissions_Reader:
		aclPerms = list.AclPermissionsReader
	case model.ParticipantPermissions_Writer:
		aclPerms = list.AclPermissionsWriter
	case model.ParticipantPermissions_Admin:
		aclPerms = list.AclPermissionsAdmin
	}
	cl := acceptSpace.CommonSpace().AclClient()
	a.aclClientLock.Lock()
	defer a.aclClientLock.Unlock()
	err = cl.AcceptRequest(ctx, list.RequestAcceptPayload{
		RequestRecordId: recId,
		Permissions:     aclPerms,
	})
	if err != nil {
		return convertedOrAclRequestError(err)
	}
	return nil
}

func (a *aclService) GetCurrentInvite(ctx context.Context, spaceId string) (domain.InviteInfo, error) {
	return a.inviteService.GetCurrent(ctx, spaceId)
}

func (a *aclService) ChangeInvite(ctx context.Context, spaceId string, permissions model.ParticipantPermissions) (err error) {
	if spaceId == a.accountService.PersonalSpaceID() {
		err = ErrPersonalSpace
		return
	}
	current, err := a.inviteService.GetCurrent(ctx, spaceId)
	if err == nil {
		if current.InviteType != domain.InviteTypeAnyone {
			return inviteservice.ErrInviteNotExists
		}
		// the invite is shared within the space, so raising it above read access would leave a link that
		// lets whoever holds it write, in the hands of every member. Generating such an invite is
		// refused; changing one into it is refused for the same reason
		if !current.HeldByOwner && !domain.ShareableWithinSpace(current.InviteType, domain.ConvertParticipantPermissions(permissions)) {
			return inviteservice.ErrInviteNotShareable
		}
	}
	acceptSpace, err := a.spaceService.Get(ctx, spaceId)
	if err != nil {
		return convertedOrSpaceErr(err)
	}
	aclClient := acceptSpace.CommonSpace().AclClient()
	acl := acceptSpace.CommonSpace().Acl()
	acl.RLock()
	invites := acl.AclState().Invites(aclrecordproto.AclInviteType_AnyoneCanJoin)
	if len(invites) == 0 {
		acl.RUnlock()
		return inviteservice.ErrInviteNotExists
	}
	acl.RUnlock()
	var (
		invite            = invites[0]
		invitePermissions = domain.ConvertParticipantPermissions(permissions)
	)
	if invite.Permissions == invitePermissions {
		return ErrIncorrectPermissions
	}
	a.aclClientLock.Lock()
	err = aclClient.ChangeInvitePermissions(ctx, invites[0].Id, invitePermissions)
	a.aclClientLock.Unlock()
	if err != nil {
		return convertedOrAclRequestError(err)
	}
	err = a.inviteService.Change(ctx, spaceId, invitePermissions)
	if err != nil {
		return convertedOrInternalError("change invite", err)
	}
	return nil
}

func (a *aclService) GenerateInvite(ctx context.Context, spaceId string, invType model.InviteType, permissions model.ParticipantPermissions, shareWithinSpace bool) (result domain.InviteInfo, err error) {
	if spaceId == a.accountService.PersonalSpaceID() {
		err = ErrPersonalSpace
		return
	}
	inviteType := domain.InviteType(invType)
	if shareWithinSpace && !domain.ShareableWithinSpace(inviteType, domain.ConvertParticipantPermissions(permissions)) {
		return domain.InviteInfo{}, inviteservice.ErrInviteNotShareable
	}
	current, err := a.inviteService.GetCurrent(ctx, spaceId)
	// an invite this device cannot read comes back without a cid: it is held by the owner, and only
	// they can do anything with it
	if err == nil && current.InviteFileCid != "" && current.InviteType == inviteType {
		switch {
		case current.HeldByOwner == !shareWithinSpace:
			return current, nil
		case shareWithinSpace:
			// the invite the owner holds is published into the workspace. It is the same invite: nothing
			// is revoked, no new file is stored, and the link the owner already handed out keeps working
			return a.inviteService.ShareWithinSpace(ctx, spaceId)
		default:
			// the other way round is not something we can honour. The workspace's change history has
			// already given this invite's cid and key to every member of the space; taking the details
			// back out of the workspace would not take the invite back. Revoking it would, and that is
			// the client's call to make, not ours
			return domain.InviteInfo{}, ErrInviteAlreadyShared
		}
	}
	acceptSpace, err := a.spaceService.Get(ctx, spaceId)
	if err != nil {
		return
	}
	commonSpace := acceptSpace.CommonSpace()
	acl := commonSpace.Acl()
	// only the owner may create an invite. The any-sync node rejects a non-owner's invite record too, but
	// checking here keeps admins from ever building or storing one in the first place.
	acl.RLock()
	isOwner := acl.AclState().Permissions(acl.AclState().Identity()).IsOwner()
	acl.RUnlock()
	if !isOwner {
		return domain.InviteInfo{}, ErrIncorrectPermissions
	}
	aclClient := commonSpace.AclClient()
	aclPermissions := domain.ConvertParticipantPermissions(permissions)
	invitePayload := aclclient.InvitePayload{
		Permissions: aclPermissions,
		InviteType:  domain.ConvertInviteType(inviteType),
	}
	// ReplaceInvite revokes whatever invite the space has, which happens here whenever the invite type
	// changes: an invite of the same type would have been returned above instead
	replaces := current.InviteFileCid != ""

	// the lock is released before the invite is reported as revoked: onInviteRevoked reaches the tech
	// space and the file node, and aclClientLock serializes every acl operation of every space
	var revokedEarly bool
	result, err = func() (domain.InviteInfo, error) {
		a.aclClientLock.Lock()
		defer a.aclClientLock.Unlock()
		// an anyone-can-join invite embeds the read key. Before replacing it, revoke it and rotate, so the
		// key it handed out cannot read what the new invite's members go on to write. ReplaceInvite cannot
		// do this in one record — a new invite in the same record would embed the pre-rotation key — so it
		// is a separate record, and the ReplaceInvite below then has nothing left to revoke.
		if hasAnyoneCanJoinInvite(acl) {
			change, err := newReadKeyChange()
			if err != nil {
				return domain.InviteInfo{}, convertedOrInternalError("generate read key change", err)
			}
			if err := aclClient.RevokeAllInvitesAndRotate(ctx, change); err != nil {
				return domain.InviteInfo{}, convertedOrInternalError("revoke and rotate invites", err)
			}
			revokedEarly = true
			// The invite the details point at is revoked as of the record above, so clear them before the
			// new invite's round trips rather than after: should anything below fail, GetCurrent then
			// answers "no invite" instead of advertising a dead link, and a retry falls past the
			// early-return above and generates cleanly. Best effort — on success setInviteInfo overwrites
			// the details anyway, and a failed clear merely leaves the window this shrinks.
			if _, err := a.inviteService.RemoveExisting(ctx, spaceId); err != nil {
				log.Warn("clear details of a replaced invite", zap.String("spaceId", spaceId), zap.Error(err))
			}
		}
		res, err := aclClient.ReplaceInvite(ctx, invitePayload)
		if err != nil {
			return domain.InviteInfo{}, convertedOrInternalError("couldn't generate acl invite", err)
		}
		params := inviteservice.GenerateInviteParams{
			SpaceId:          spaceId,
			Key:              res.InviteKey,
			InviteType:       inviteType,
			Permissions:      aclPermissions,
			ShareWithinSpace: shareWithinSpace,
		}
		return a.inviteService.Generate(ctx, params, func() error {
			if err := aclClient.AddRecord(ctx, res.InviteRec); err != nil {
				return convertedOrAclRequestError(err)
			}
			return nil
		})
	}()
	// on success the old invite is revoked by ReplaceInvite; on a mid-flight failure it is revoked all
	// the same when the rotation record went through first — report it either way, so its file is
	// deleted now rather than by the next launch's sweep
	if replaces && (err == nil || revokedEarly) {
		a.onInviteRevoked(ctx, spaceId, current)
	}
	return result, err
}

func (a *aclService) GetGuestUserInvite(ctx context.Context, spaceId string) (info domain.InviteInfo, err error) {
	if spaceId == a.accountService.PersonalSpaceID() {
		err = ErrPersonalSpace
		return
	}
	current, err := a.inviteService.GetExistingGuestUserInvite(ctx, spaceId)
	if err == nil {
		return current, nil
	}
	var shareableStatus spaceinfo.ShareableStatus
	err = a.spaceService.TechSpace().DoSpaceView(ctx, spaceId, func(spaceView techspace.SpaceView) error {
		localInfo := spaceView.GetLocalInfo()
		shareableStatus = localInfo.GetShareableStatus()
		return nil
	})
	if err != nil {
		return
	}

	if shareableStatus != spaceinfo.ShareableStatusShareable {
		err = a.MakeShareable(ctx, spaceId)
		if err != nil {
			return
		}
	}
	// todo: race conds in case guest user already created?
	// we can iterate users to find the guest key
	guestKey, err := a.AddGuestAccount(ctx, spaceId)
	if err != nil {
		return domain.InviteInfo{}, convertedOrInternalError("add guest account", err)
	}
	info, err = a.inviteService.GenerateGuestUserInvite(ctx, spaceId, guestKey)
	if err != nil {
		return domain.InviteInfo{}, convertedOrInternalError("generate guest user invite", err)
	}
	return
}

func (a *aclService) joinAsGuest(ctx context.Context, spaceId string, guestUserKey crypto.PrivKey) (err error) {
	return a.spaceService.AddStreamable(ctx, spaceId, guestUserKey)
}

func (a *aclService) OwnershipChange(ctx context.Context, spaceId string, newOwner crypto.PubKey, oldOwnerPerm model.ParticipantPermissions) (err error) {
	if spaceId == a.accountService.PersonalSpaceID() {
		err = ErrPersonalSpace
		return
	}
	ownedSpace, err := a.spaceService.Get(ctx, spaceId)
	if err != nil {
		return convertedOrSpaceErr(err)
	}
	aclClient := ownedSpace.CommonSpace().AclClient()
	a.aclClientLock.Lock()
	defer a.aclClientLock.Unlock()
	return aclClient.OwnershipChange(ctx, newOwner, domain.ConvertParticipantPermissions(oldOwnerPerm))
}

core/acl/aclgetter.go.text:
package acl

import (
	"context"
	"fmt"
	"sync"

	"github.com/anyproto/any-sync/commonspace/acl/aclclient"
	"github.com/anyproto/any-sync/commonspace/object/accountdata"
	"github.com/anyproto/any-sync/commonspace/object/acl/list"
	"github.com/anyproto/any-sync/commonspace/object/acl/recordverifier"
	"github.com/anyproto/any-sync/nodeconf"
	"github.com/anyproto/any-sync/util/crypto"
)

type aclGetter struct {
	mu          sync.Mutex // guards currentAcls (Leave runs without aclClientLock and may run concurrently)
	currentAcls map[string]list.AclList
	aclClient   aclclient.AclJoiningClient
	keys        *accountdata.AccountKeys
	nodeConf    nodeconf.NodeConf
}

func newAclGetter(aclClient aclclient.AclJoiningClient, keys *accountdata.AccountKeys, nodeConf nodeconf.NodeConf) *aclGetter {
	return &aclGetter{
		currentAcls: make(map[string]list.AclList),
		aclClient:   aclClient,
		keys:        keys,
		nodeConf:    nodeConf,
	}
}

func (g *aclGetter) RemoveAcl(ctx context.Context, spaceId string) error {
	g.mu.Lock()
	delete(g.currentAcls, spaceId)
	g.mu.Unlock()
	return nil
}

func (g *aclGetter) GetOrRefreshAcl(ctx context.Context, spaceId string) (aclList list.AclList, err error) {
	g.mu.Lock()
	aclList, ok := g.currentAcls[spaceId]
	g.mu.Unlock()
	if ok {
		if err := g.refresh(ctx, spaceId, aclList); err != nil {
			return nil, err
		}
		return aclList, nil
	}
	// fetch outside the lock (network call), then publish, double-checking another goroutine didn't win.
	fetched, err := g.getAcl(ctx, spaceId)
	if err != nil {
		return nil, err
	}
	g.mu.Lock()
	if existing, ok := g.currentAcls[spaceId]; ok {
		fetched = existing
	} else {
		g.currentAcls[spaceId] = fetched
	}
	g.mu.Unlock()
	return fetched, nil
}

func (g *aclGetter) getAcl(ctx context.Context, spaceId string) (l list.AclList, err error) {
	res, err := g.aclClient.AclGetRecords(ctx, spaceId, "")
	if err != nil {
		return
	}
	if len(res) == 0 {
		err = fmt.Errorf("acl not found")
		return
	}
	storage, err := list.NewInMemoryStorage(res[0].Id, res)
	if err != nil {
		return
	}
	verifier := recordverifier.NewValidateFull()
	if networkId := g.nodeConf.Configuration().NetworkId; networkId != "" {
		netKey, decodeErr := crypto.DecodeNetworkId(networkId)
		if decodeErr != nil {
			return nil, fmt.Errorf("invalid networkId: %w", decodeErr)
		}
		verifier = recordverifier.New(netKey)
	}
	return list.BuildAclListWithIdentity(g.keys, storage, verifier)
}

func (g *aclGetter) refresh(ctx context.Context, spaceId string, aclList list.AclList) (err error) {
	res, err := g.aclClient.AclGetRecords(ctx, spaceId, aclList.Head().Id)
	if err != nil {
		return
	}
	if len(res) == 0 {
		return
	}
	return aclList.AddRawRecords(res)
}
